(function () {
"use strict";
const weeks = [
["Как историки узнают прошлое","Как отличить свидетельство от интерпретации и построить проверяемый вывод?","Исторический метод и аргументация",[["Первичный источник","Создан участником или в эпоху изучаемых событий; сам по себе не гарантирует правдивость."],["Контекст","Обстоятельства, в которых источник появился и приобрёл смысл."],["Сопоставление источников","Проверка утверждения через независимые свидетельства; в академической литературе также используется термин «корроборация»."]],"https://openstax.org/books/world-history-volume-1/pages/1-introduction","История — не готовый список истин и не простое мнение о прошлом. Историк формулирует вопрос, находит свидетельства, проверяет происхождение и контекст источников, сравнивает версии и объясняет, почему одни выводы убедительнее других. Документ может быть подлинным, но ошибаться; воспоминание — искренним, но избирательным; изображение — ярким, но созданным десятилетия после события. Поэтому хороший вывод указывает не только что произошло, но и на каких основаниях мы это утверждаем.","Начните с любого знакомого вам события: попробуйте отделить установленный факт, объяснение причин и личную оценку. Это три разные вещи.",[
["Что изучает история?","Методы историка","Почему мы не можем просто переписать прошлое из одного источника?","История реконструирует прошлое с помощью сохранившихся свидетельств. Источники фрагментарны, создаются людьми с определёнными знаниями и целями, а часть опыта вообще могла не оставить письменных следов. Историк обязан объяснять, почему доверяет конкретному свидетельству, как соотносит его с другими данными и где сохраняется неопределённость.","Документ и его интерпретация — не одно и то же.","Отсутствие письменного источника не означает отсутствия истории.","Выводы пересматриваются при появлении новых доказательств.","Historical_method","historical evidence archive museum documents","Возьмите одно утверждение о прошлом и разделите ответ на факт, интерпретацию и оценку.","Отметьте границу между данными и вашим выводом; объясните, какие свидетельства нужны."],
["Хронология и историческое время","Даты, периоды, масштабы","Зачем периодизировать прошлое, если история непрерывна?","Хронология помогает упорядочить события, но исторические периоды — аналитические инструменты, а не природные границы. «Средневековье», «Новое время» или «революция» могут начинаться в разные моменты для разных регионов. Учитесь одновременно видеть последовательность событий и процессы, которые развиваются десятилетиями или веками.","В традиционной исторической системе нет нулевого года: 1 год до н. э. сменяется 1 годом н. э.; даты до н. э. идут к началу нашей эры в обратном порядке.","Периодизация зависит от вопроса и региона.","Одновременность событий в разных местах часто выявляет глобальные связи.","Historical_chronology","historical timeline chronology world history","Объясните, как один и тот же век мог быть эпохой расцвета в одном регионе и кризиса в другом.","Укажите временной диапазон, регион и критерий, по которому проводится периодизация."],
["География и карта как источник","Пространство и ландшафт","Как география открывает одни возможности и ограничивает другие?","Реки, горы, степи, моря и климат влияли на земледелие, торговлю, миграции и войны, но не предопределяли судьбу общества. Карта тоже сделана кем-то для определённой задачи: её масштаб, подписи и границы могут выделять одну перспективу и скрывать другую.","Реки облегчают транспорт и орошение, но требуют управления рисками паводков.","Степь была пространством обмена и мобильности, а не пустой границей цивилизаций.","Политические карты обычно показывают контроль, а не обязательно реальную повседневную жизнь.","Historical_map","historical map physical geography trade routes","Посмотрите на карту региона и сформулируйте два возможных преимущества и два ограничения его географии.","Отделите то, что действительно показано на карте, от предположений о людях и обществе."],
["Археология и естественно-научные методы","Материальные свидетельства","Что могут рассказать кости, керамика и слой почвы, если текстов нет?","Археологи изучают расположение предметов, строительные слои, пищевые остатки и погребения. Радиоуглеродное датирование помогает оценить возраст органики; ДНК и изотопы иногда показывают родство, миграции и рацион. Любой метод имеет пределы: дата образца не всегда равна дате события, которое мы пытаемся объяснить.","Археологический контекст часто важнее красивого одиночного предмета.","Радиоуглеродный метод применим к органическим материалам в определённых временных пределах.","Данные ДНК показывают биологическое родство, но не определяют автоматически язык или идентичность.","Archaeology","archaeological excavation pottery artifacts museum","Какие вопросы о жизни древнего поселения можно изучить по мусорной яме, скелетам и керамике?","Свяжите каждый вывод с типом данных и укажите ограничение метода."],
["Первичные и вторичные источники","Документы, хроники, исследования","Почему дневник очевидца не всегда надёжнее труда историка?","Первичный источник ближе к событию, но автор мог ошибаться, лгать, скрывать сведения или писать для определённой аудитории. Вторичный труд сопоставляет множество свидетельств, однако зависит от отбора и интерпретации автора. Сильное исследование использует оба вида источников и открыто показывает ход аргумента.","Письмо солдата первично для опыта автора, но не обязательно для всей военной кампании.","Поздняя хроника может сохранять более ранние сведения, но требует проверки.","Независимость источников важна: несколько текстов могут копировать один исходный рассказ.","Primary_source","historical primary source letter diary manuscript","Выберите источник и объясните, для какого вопроса он полезен, а для какого недостаточен.","Укажите тип источника, автора, контекст и конкретный предел надёжности."],
["Пропаганда, память и спорные события","История и публичная память","Как отличить политическое использование прошлого от исторического исследования?","Государства, движения и семьи выбирают памятные даты, героев и трагедии по-разному. Историк изучает не только событие, но и то, как его описывали современники и последующие поколения. Это не означает, что все версии равны: утверждения проверяются по источникам и методам.","Память о событии меняется с поколениями и политическим контекстом.","Пропаганда может использовать правдивые детали, умалчивая неудобные факты.","Разногласие историков обычно касается аргументов и веса доказательств, а не права игнорировать источники.","Historical_revisionism","historical monument memory museum exhibit","Сравните две подписи к одному памятнику: что они выделяют и что опускают?","Назовите аудиторию, цель и умолчания, но не делайте вывод только из политической симпатии."],
["Практикум 1: разбор источника","Экзаменационная мастерская","Как за несколько минут оценить исторический документ?","Отработайте базовую схему анализа: кто создал источник, когда и где, для какой аудитории, с какой целью; что он позволяет узнать и чего не доказывает. Сначала опишите содержание, затем объясните значение, потом сопоставьте с другим источником. Это фундамент навыков AP, IB и Cambridge.","Происхождение и контекст помогают интерпретировать содержание.","Ценность источника зависит от вопроса, который ему задают.","Сильный ответ содержит тезис, точное доказательство и объяснение связи между ними.","Historical_method","historical documents source analysis classroom","Выберите короткий документ и напишите 5–7 предложений: происхождение, цель, ценность, ограничение, вывод.","Проверьте, есть ли конкретная деталь из источника и пояснение, почему она важна."]
]],
["Homo sapiens: язык, мифы и религия","Как язык, ритуалы и общие представления помогали людям сотрудничать в больших сообществах?","Когнитивная археология, религия и коллективные представления",[["Когнитивная революция","Удобное название гипотезы о крупных изменениях в коммуникации и символическом поведении Homo sapiens; точные сроки и механизм обсуждаются."],["Ритуал","Повторяющаяся символическая практика, которая может выражать принадлежность, веру, память или общественный порядок."],["Коллективное представление","Идея, правило или символ, значение которого поддерживается группой; это аналитическое понятие, а не утверждение, что вся религия выдумана."],["Синкретизм","Сочетание и взаимное изменение религиозных практик и традиций при контакте." ]],"https://www.si.edu/object/siris_sil_1040479","Люди жили в небольших мобильных сообществах задолго до городов, государств и письменности. Археология показывает орудия, украшения, изображения, погребения и монументальные места, но редко позволяет прямо узнать, во что люди верили. В книге «Sapiens» Юваль Ной Харари предлагает влиятельную большую рамку: общий язык, рассказы, символы и представления помогают людям сотрудничать за пределами семьи. Эту идею стоит использовать как каталог вопросов, а не как окончательный ответ. Доказательства происхождения религии фрагментарны; социальная роль религии не объясняет автоматически ни её происхождение, ни личную веру, ни истинность религиозных утверждений.","Представьте три артефакта: погребение, украшение и каменное сооружение. Каждый даёт подсказки, но ни один сам по себе не сообщает точное содержание веры создателей.",[
["Homo sapiens и другие человеческие виды","Плейстоцен","Что мы действительно знаем о происхождении Homo sapiens и его контактах с другими людьми?","Homo sapiens сформировался в Африке в ходе длительной эволюции популяций. Затем люди расселялись по разным регионам и взаимодействовали с другими человеческими группами, включая неандертальцев и денисовцев. Генетика, ископаемые останки и археология дают взаимодополняющие свидетельства, но не складываются в одну простую лестницу эволюции.","Африканское происхождение Homo sapiens подтверждается генетическими и ископаемыми данными.","Эволюция человека была ветвящимся процессом; на Земле одновременно существовало несколько человеческих видов.","Часть современных людей унаследовала небольшую долю ДНК от неандертальцев; следы других древних смешений изучаются.","Human_evolution","Homo sapiens Neanderthal Denisovan fossil skull museum","Как генетические, ископаемые и археологические данные вместе меняют рассказ об эволюции человека?","Сопоставьте типы свидетельств и укажите, что каждый из них не может доказать в одиночку.","Sapiens начинает с происхождения человека и подчёркивает, что наш вид долго не был единственным видом людей. Современная картина уточняется генетикой и новыми находками; не стоит превращать её в историю о неизбежном превосходстве."],
["Повседневность охотников-собирателей","Палеолит и мезолит; сроки различаются по регионам","Почему мобильные общества не следует считать просто отсталыми земледельческими обществами?","Охота, рыболовство и собирательство требовали глубоких знаний сезонности, животных, растений, воды и ландшафта. Мобильность могла уменьшать некоторые риски, поддерживать гибкое использование ресурсов и ограничивать накопление запасов, но создавала другие трудности. Нельзя обобщать опыт всех охотников-собирателей: их общества различались по климату, технологиям и социальным практикам.","Стратегии выживания отличались от арктических регионов до тропиков и морских побережий.","Для мобильных групп знание ландшафта и передача навыков были критически важны.","Поздние этнографические наблюдения о современных охотниках-собирателях не являются прямой фотографией палеолита.","Hunter_gatherer","hunter gatherer daily life stone tools archaeological reconstruction","Какие преимущества и издержки мобильного образа жизни можно вывести из условий среды?","Выберите несколько условий и постройте причинную связь, не делая выводов обо всех обществах сразу.","В «Sapiens» повседневность охотников-собирателей служит контрастом более поздним обществам. Это полезный способ поставить вопрос, но общую оценку счастья, здоровья или свободы нельзя надёжно вывести из нескольких современных аналогий."],
["Когнитивная революция: язык, символы и сотрудничество","Поздний палеолит; интерпретации и датировки обсуждаются","Как символы и коммуникация могли расширить круг совместных действий?","Археологические свидетельства сложного символического поведения, украшений, дальнего обмена и искусства указывают, что человеческие группы развивали богатые способы общения. «Когнитивная революция» — влиятельная гипотеза и название в книге Харари, но не общепринятая точная дата единственного скачка: изменения, вероятно, происходили неравномерно и постепенно.","Украшения и изображения свидетельствуют о символической практике, но их смысл не всегда известен.","Символы помогают передавать принадлежность, память и правила, но конкретное значение нуждается в контексте.","Исследователи спорят о темпах, причинах и географии появления поведенческой современности.","Cognitive_revolution","Upper Paleolithic cave art beads engravings symbolic artifacts","Как символическая коммуникация могла помочь людям координировать действия за пределами небольшой семьи?","Предложите механизм и отделите правдоподобную гипотезу от прямого археологического свидетельства.","Харари связывает когнитивные изменения со способностью создавать общие истории. Используйте это как сильную гипотезу для обсуждения, а не как доказанный единственный механизм человеческого успеха."],
["Общие истории, нормы и большие сообщества","Доистория — современность","Как незнакомые люди могут сотрудничать, если лично не знают друг друга?","Люди способны координироваться через язык, нормы, символы, право, ритуалы, деньги и представления о принадлежности. Харари называет некоторые такие системы «общими вымыслами» или коллективными представлениями; термин провокационный, поскольку социальные институты могут быть созданными людьми, но их последствия вполне материальны. Не всё коллективное сводится к обману или сознательному изобретению.","Деньги работают, когда участники доверяют правилам обмена и институтам.","Государства используют законы, символы и ритуалы для определения принадлежности и обязанностей.","Общие представления не отменяют принуждения, неравенства или искренней веры участников.","Imagined_order","money coin national flag law code ritual symbols","Как общая норма может одновременно облегчать сотрудничество и поддерживать исключение некоторых людей?","Выберите пример из денег, гражданства, права или религии и покажите обе стороны.","Это один из центральных тезисов «Sapiens». Он особенно полезен для вопросов о деньгах, империях и институтах, но метафору «вымысла» нельзя автоматически переносить на все религиозные переживания."],
["Что археология может сказать о ранней религии?","Доистория; конкретные датировки зависят от находки","Как исследовать верования, если у людей не было письменных объяснений?","Погребальные практики, необычные места собраний, изображения и символические предметы могут указывать на ритуальное поведение. Однако интерпретации неоднозначны: погребальный дар может иметь разные значения, а изображение не сообщает само по себе миф, молитву или представление о загробной жизни. Историк должен показать, где заканчиваются наблюдаемые данные и начинается гипотеза.","Погребения с предметами могут свидетельствовать о ритуалах, но не дают однозначной теологии.","Символический предмет нужно рассматривать в археологическом контексте, а не отдельно.","Отсутствие сохранившегося текста ограничивает точность реконструкции, но не делает исследование невозможным.","Prehistoric_religion","prehistoric burial grave goods cave art ritual archaeology","Какая интерпретация погребения является осторожной, а какая выдаёт предположение за факт?","Выберите утверждение, которое признаёт несколько возможных объяснений и необходимость сравнения находок.","Религия не появляется в археологии как готовая категория. Исследователи выводят наличие ритуала из нескольких признаков и спорят о том, как далеко можно идти в реконструкции верований."],
["Гёбекли-Тепе: ритуал до полного перехода к земледелию?","Примерно X–IX тысячелетия до н. э.; датировка и интерпретация уточняются","Почему Гёбекли-Тепе усложняет простой рассказ о происхождении храмов и государств?","Гёбекли-Тепе на территории современной Турции содержит монументальные каменные сооружения, датируемые ранним докерамическим неолитом. Его часто связывают с ритуальной деятельностью, однако точная функция комплекса и организация труда остаются предметом исследований. Памятник показывает, что монументальная коллективная деятельность могла развиваться в обществах, не похожих на позднейшие земледельческие государства.","Крупные каменные сооружения относятся к раннему докерамическому неолиту.","Ритуальная интерпретация широко обсуждается, но детали назначения не установлены окончательно.","Памятник не доказывает универсальное правило, будто религия везде возникла раньше земледелия или наоборот.","Gobekli_Tepe","Gobekli Tepe T shaped pillars archaeological site","Какой вывод надёжнее: «это точно храм с известным культом» или «это монументальный комплекс, вероятно связанный с коллективными ритуалами»?","Выберите формулировку, которая соответствует уровню доказательств, и объясните её преимущество.","Этот пример полезно сопоставлять с тезисом «Sapiens», что большие проекты могут организовывать сотрудничество. Но один памятник не доказывает универсальную теорию происхождения религии."],
["Религия: социальная функция, вера и историческое доказательство","Древность — современность","Можно ли объяснить религию только её пользой для общества?","Религии могут связывать общины, обосновывать власть, задавать нормы, объяснять мир, организовывать ритуалы и давать людям язык смысла и опыта. Эти социальные функции не исчерпывают религиозную жизнь. Объяснение того, как вера влияет на общество, само по себе не доказывает ни её истинность, ни ложность. Монотеизм также не следует описывать как одну простую линейную ступень после политеизма: исторические традиции развивались сложнее.","В Месопотамии и Египте религиозные ритуалы были связаны с царской властью, но местные верования отличались.","Буддизм, индуистские традиции, иудаизм, христианство и ислам имеют различные истории, институты и представления.","Религия могла поддерживать власть, но также становиться источником критики, реформы и сопротивления.","Religion","ancient religious artifacts temple mosque church Buddhist stupa","Какой вывод следует из того, что религия помогает организовывать общество, а какой из этого не следует?","Выберите ответ, который различает социальную функцию, историческое происхождение и вопрос веры.","Здесь полезно сопоставить Харари с историками религии и антропологами. Большая синтеза помогает заметить закономерности, но её широкие обобщения нужно проверять на конкретных традициях и источниках."]
]],
["Неолит и первые государства","Почему земледелие изменило расселение, власть и социальное неравенство?","Переход к земледелию и урбанизация",[["Неолитическая революция","Переход ряда обществ к выращиванию растений и одомашниванию животных."],["Ирригация","Управляемое снабжение полей водой."],["Город-государство","Город и окружающая территория под единым политическим управлением."]],"https://openstax.org/books/world-history-volume-1/pages/3-introduction","Земледелие развивалось постепенно и независимо в нескольких частях мира. Оседлость и хранение урожая помогали поддерживать более плотное население и специализированный труд, но могли приносить болезни, зависимость от урожая, конфликты за землю и более выраженное имущественное неравенство. В Месопотамии и Египте первые государства возникали в связи с земледелием, торговлей, религиозными институтами и управлением ресурсами.","Сравните две семьи: одна перемещается вслед за сезонной пищей, другая выращивает зерно и хранит излишки. У каждой модели есть свои выгоды и уязвимости.",[
["Почему возникло земледелие?","Около 10 000 лет до н. э. и позже","Было ли земледелие неизбежным шагом к лучшей жизни?","Одомашнивание растений и животных появлялось в разных регионах и не было единым событием. Земледелие позволяло увеличивать запасы и население, но требовало тяжёлого труда и делало людей зависимыми от урожая, вредителей и контроля над землёй.","Ранние центры земледелия включали Плодородный полумесяц, Китай, Новую Гвинею и Америки.","Некоторые общества долго сочетали земледелие с охотой и собирательством.","Оседлость часто сопровождалась изменениями здоровья и социальной структуры.","Neolithic_Revolution","Neolithic farming early agriculture archaeological site","Сравните земледелие и собирательство по трём критериям, не называя одно универсально лучшим.","Приведите баланс преимуществ и издержек."],
["Плодородный полумесяц и первые деревни","X–VII тысячелетия до н. э.","Как растения, животные и деревни изменили жизнь людей?","В некоторых поселениях Юго-Западной Азии одомашнивание зерновых и животных шло постепенно. Деревни создавали условия для хранения пищи, ремёсел и обмена, но требовали коллективных правил распределения земли и воды.","Пшеница, ячмень, овцы и козы были важны для ряда ранних земледельческих обществ.","Одомашнивание — долгий процесс отбора, а не одномоментное изобретение.","Поселения вроде Иерихона показывают сложные формы раннего оседлого общества.","Fertile_Crescent","Jericho Neolithic settlement archaeology","Как земледелие могло одновременно повышать устойчивость и создавать новые риски?","Постройте причинную цепочку с обоими направлениями."],
["Шумерские города и клинопись","IV–III тысячелетия до н. э.","Зачем ранним городам понадобилась письменность?","Города южной Месопотамии объединяли земледелие, храмы, ремесло и торговлю. Ранние клинописные записи часто служили учёту товаров и обязательств; со временем письменность стала средством литературы, дипломатии и передачи знаний.","Урук был одним из крупнейших центров ранней городской цивилизации.","Клинописные знаки развивались из систем учёта.","Города-государства соперничали, заключали союзы и создавали собственные культы.","Sumer","Sumerian cuneiform tablet Uruk","Почему потребность считать зерно и труд могла привести к развитию письменности?","Укажите связь между административной задачей и новой технологией."],
["Вавилон и законы Хаммурапи","XVIII век до н. э.","Можно ли по древнему кодексу понять, как на самом деле судили людей?","Законы Хаммурапи демонстрируют, как царь представлял справедливость и порядок. Они важны как источник политической идеологии и социального статуса, но не являются полным отчётом обо всех судебных делах и повседневной практике.","Кодекс различал социальные статусы и предусматривал разные санкции.","Текст подчёркивал царскую роль как гаранта справедливости.","Нормативный текст сообщает, что власть хотела провозгласить, а не обязательно что происходило в каждом суде.","Code_of_Hammurabi","Code of Hammurabi stele museum","Чем закон как предписание отличается от источника о реальной практике?","Назовите ценность и ограничение нормативного источника."],
["Древний Египет и Нил","Около 3100–30 годов до н. э.","Как река и политическая власть поддерживали египетское государство?","Циклы Нила поддерживали сельское хозяйство и связывали поселения вдоль долины. Фараон представлялся гарантом космического и общественного порядка; администрация организовывала налоги, строительство и перераспределение ресурсов. Однако Египет менялся через периоды централизации, кризисов и внешних контактов.","Объединение Верхнего и Нижнего Египта обычно датируют около 3100 года до н. э.","Нил был транспортной артерией и основой земледельческого календаря.","Монументальные гробницы показывают ресурсы государства и религиозные представления, но не всю жизнь населения.","Ancient_Egypt","ancient Egypt Nile tomb painting agricultural scene","Как природный цикл мог укреплять власть, но также делать государство уязвимым?","Свяжите экологию, продовольствие и легитимность власти."],
["Ремесло, торговля и бронзовый век","III–II тысячелетия до н. э.","Почему древние государства зависели от сетей обмена?","Металлы, дерево, камень и другие ресурсы часто находились далеко от крупных центров. Торговые сети связывали города, передавали технологии и создавали зависимость от посредников. Бронзовый век показывает, что сложные общества существовали благодаря не только земледелию, но и дальнему обмену.","Олово и медь для бронзы поступали из разных мест.","Письмо и печати помогали оформлять учёт и торговые операции.","Дипломатические письма Амарны демонстрируют связи правителей Восточного Средиземноморья.","Bronze_Age","Bronze Age trade routes artifacts pottery","Как перебой поставок металла мог изменить политику и военную силу государства?","Покажите минимум два промежуточных звена между торговлей и политикой."],
["Практикум 3: сравнить речные цивилизации","Около IV–II тысячелетий до н. э.","Почему Месопотамия и Египет были похожи, но не одинаковы?","Обе области опирались на земледелие, реки и административные институты, однако различия ландшафта, политической раздробленности и внешних связей влияли на формы власти. Сравнение должно объяснять причины различий, а не ограничиваться перечнем сходств.","Месопотамия часто была разделена на конкурирующие города-государства.","Египетские периоды объединения опирались на долину Нила и царскую идеологию.","В обоих регионах письменные источники преимущественно отражают взгляды грамотных элит.","Ancient_Near_East","Mesopotamia Egypt ancient civilization map","Напишите короткий ответ: один фактор сходства и два фактора различий между Египтом и Месопотамией.","Тезис должен назвать регионы и объяснить, как фактор вызвал различие."]
]],
["Древняя Индия, Китай и ранняя Азия","Как складывались разные модели власти, культуры и городской жизни в Азии?","Цивилизации и институты",[["Хараппская цивилизация","Городская культура долины Инда, известная по планировке поселений и материальным находкам."],["Династия","Правящая линия, в которой власть часто передаётся внутри рода."],["Конфуцианство","Традиция этики и политической мысли, связанная с Конфуцием и его последователями."]],"https://openstax.org/books/world-history-volume-1/pages/5-introduction","Ранние общества Южной и Восточной Азии нельзя сводить к одному пути развития. Города долины Инда были связаны с торговлей и тщательно планировались, но их письменность пока не прочитана. В Китае археология и надписи показывают смену династий, бронзовую технологию и идеи о легитимности правления. Научная осторожность особенно важна, когда источники фрагментарны или позднее мифологизированы.","Сравните общество с письменностью, которую мы умеем читать, и общество с нерасшифрованными знаками: что мы можем утверждать с разной степенью уверенности?",[
["Хараппа и Мохенджо-Даро","Около 2600–1900 годов до н. э.","Почему города Инда требуют осторожной интерпретации?","Хараппская цивилизация имела развитую городскую планировку, стандартизированные кирпичи, системы водоотведения и дальнюю торговлю. Однако письменность остаётся нерасшифрованной, поэтому реконструкции власти, религии и языка остаются ограниченными.","Основные городские центры находились в долине Инда и соседних регионах.","Печати и стандарты указывают на связанные экономические практики.","Археология позволяет описывать города, но не даёт уверенно прочитать их политические тексты.","Indus_Valley_Civilisation","Mohenjo-daro Great Bath Indus seals archaeology","Какие утверждения о долине Инда можно сделать по городской планировке, а какие пока нельзя?","Разделите наблюдаемые данные и гипотезы о политике или религии."],
["Ведийский мир и социальная иерархия","II–I тысячелетия до н. э.","Как менялись религиозные традиции и социальные институты Южной Азии?","Ведийские тексты отражают ритуальную и общественную жизнь части древнеиндийских сообществ. Варновые модели и позднейшие кастовые структуры менялись исторически; их нельзя представлять неизменными с глубокой древности. Городская жизнь и торговля продолжали влиять на разнообразие региона.","Веды передавались устно до фиксации в письменных формах.","Варна и джати — связанные, но не тождественные понятия.","Религиозные и социальные практики различались по регионам и эпохам.","Vedic_period","Vedic India ancient manuscript ritual","Почему опасно переносить позднейшую кастовую систему целиком на ранний ведийский период?","Укажите изменение во времени и предел поздних источников."],
["Шан и Чжоу: власть, ритуал и бронза","II–I тысячелетия до н. э.","Как ранние китайские надписи помогают изучать власть?","Надписи на гадательных костях Шан и бронзовые надписи дают ранние свидетельства о ритуале, войне и царской власти. При Чжоу развивалась идея Небесного мандата — обоснование правления, которое позволяло объяснять как успех династии, так и потерю ею власти.","Археология подтверждает существование Шан и развитую бронзовую культуру.","Надписи гадательных костей — важные первичные источники.","Небесный мандат стал влиятельным языком легитимации, а не современным конституционным механизмом.","Shang_dynasty","Shang dynasty oracle bones bronze vessel","Что источник гадательной кости сообщает о вопросах, которыми занималась царская власть?","Приведите пример сведений, которые прямо следуют из типа источника."],
["Нубия и Куш: государства к югу от Египта","II тысячелетие до н. э. — IV век н. э.","Почему историю долины Нила нужно изучать по обе стороны пустыни?","Нубийские и кушитские государства были самостоятельными политическими центрами с собственными традициями, торговлей и военной силой. В разные периоды Куш соперничал с Египтом, торговал с соседями и даже правил Египтом как XXV династия.","Кушитские центры включали Напату и Мероэ.","Мероэ развивало собственные формы письма и металлургии.","Связи Египта и Нубии сочетали войну, обмен и культурное влияние.","Kingdom_of_Kush","Kingdom of Kush Meroe pyramids archaeology","Почему выражение «Египет распространял цивилизацию на юг» слишком упрощает историю Нубии?","Укажите свидетельства самостоятельной политической и культурной деятельности."],
["Ольмеки и ранние общества Мезоамерики","II–I тысячелетия до н. э.","Какие признаки сложного общества видны без письменных хроник?","Ольмекские центры Мезоамерики оставили монументальные скульптуры, церемониальные пространства и свидетельства дальних обменных связей. Их влияние на последующие культуры обсуждается исследователями; не следует автоматически считать все более поздние достижения простым заимствованием.","Сан-Лоренсо и Ла-Вента — известные ольмекские центры.","Колоссальные головы свидетельствуют о значительных организационных ресурсах.","Археологические комплексы дают больше информации о ритуале и власти, чем о точных именах правителей.","Olmec","Olmec colossal head museum","Как памятник позволяет судить о ресурсах и организации, но не обязательно о политическом устройстве?","Разделите прямое свидетельство и возможную интерпретацию."],
["Ранние общества Анд","III–I тысячелетия до н. э.","Как города и обмен возникали без копирования ближневосточной модели?","В Андах ранние центры развивались благодаря сочетанию рыболовства, земледелия, управления водой и обмена между разными высотными зонами. Караль-Супе показывает, что монументальная архитектура и сложная организация могли появляться без тех же культурных условий, что в Евразии.","Караль-Супе относится к ранним городским центрам Перу.","Экологические зоны Анд дополняли друг друга продуктами и ресурсами.","История Америк имеет независимые траектории сложного общественного развития.","Caral_Supe_civilization","Caral Peru archaeological site Andes","Что пример Анд показывает об ошибочности идеи единственного пути к государству?","Сравните экологические условия и способы кооперации."],
["Практикум 4: сравнение ранних обществ Азии","Древний мир","Как сравнивать общества, если источники сохранились неравномерно?","Для долины Инда доступна главным образом материальная культура и нерасшифрованные знаки; для раннего Китая есть археология и читаемые надписи; для ведийской традиции важны устно передаваемые тексты. Метод должен учитывать разные возможности доказательства.","Разные источники создают разные уровни уверенности.","Отсутствие расшифрованного текста — не доказательство отсутствия институтов.","Сравнение по одинаковым критериям помогает увидеть ограничения каждой реконструкции.","Ancient_India","Indus seals Shang oracle bone ancient India map","Сопоставьте два общества по власти, хозяйству и доступности источников.","Обязательно поясните, почему уверенность в выводах различается."]
]],
["Греция, Персия и Средиземноморье","Как разные политические модели и войны меняли античный мир?","Гражданство, империя, идеи",[["Полис","Самостоятельное политическое сообщество Древней Греции."],["Гражданство","Юридический и политический статус, который определяет права и обязанности."],["Империя","Власть над большими территориями и различными народами, часто через неравные отношения."]],"https://openstax.org/books/world-history-volume-1/pages/6-introduction","Греческие полисы, Персидская империя и позднее эллинистические государства предлагали разные способы объединять людей и управлять территориями. Афины известны политическим участием граждан, но гражданство исключало значительную часть населения. Персидское царство управляло многообразными областями через провинциальные структуры и местные элиты. Ни демократия, ни империя не были однородными или неизменными понятиями.","Представьте политическую карту и спросите не только кто контролирует территорию, но и кто принимает решения, кто платит налоги и кто имеет право голоса.",[
["Минойцы, Микены и ранний греческий мир","III–II тысячелетия до н. э.","Как археология помогает изучать раннюю Грецию?","Дворцовые центры Крита и материковой Греции участвовали в обменных сетях Восточного Средиземноморья. Линейное письмо Б использовалось для административного учёта микенского греческого языка, а его расшифровка позволила связать археологические находки с конкретными хозяйственными практиками.","Кносс — важный минойский дворцовый центр.","Линейное письмо Б расшифровано; линейное письмо А остаётся нерасшифрованным.","Крах ряда дворцовых центров около 1200 года до н. э. имел несколько региональных причин.","Minoan_civilization","Knossos palace fresco Mycenaean Linear B tablet","Что расшифровка письма меняет в интерпретации археологического поселения?","Сопоставьте материальный предмет с информацией из читаемого текста."],
["Персидская империя Ахеменидов","Около 550–330 годов до н. э.","Как Персия управляла огромным разнообразным пространством?","Ахеменидские правители сочетали царскую власть, сатрапии, дороги, налогообложение и взаимодействие с местными элитами. Империя не была просто единым культурным блоком: управление учитывало региональные различия, одновременно требуя ресурсов для двора и армии.","Кир II создал основу имперского расширения в VI веке до н. э.","Дороги и курьерские сети ускоряли передачу приказов.","Персепольские рельефы изображали подношения народов как символ царского порядка.","Achaemenid_Empire","Persepolis relief Achaemenid Empire map","Как рельеф в Персеполе мог одновременно сообщать информацию и легитимировать власть?","Проанализируйте аудиторию, символизм и границы изображения как источника."],
["Персидские войны и Афины","499–449 годы до н. э.","Почему победа над Персией изменила баланс сил между греческими полисами?","Конфликты греческих полисов с Персидской империей укрепили престиж Афин и способствовали созданию морского союза. Со временем союз превратился в инструмент афинского доминирования, что усилило напряжение с другими полисами.","Марафонская битва произошла в 490 году до н. э.","Афинская морская мощь сыграла значительную роль при Саламине в 480 году до н. э.","Победа над внешним противником не устранила соперничество внутри Греции.","Greco_Persian_Wars","Battle of Salamis ancient Greek trireme illustration","Объясните, как один и тот же военный успех мог создать и безопасность, и новые конфликты.","Покажите два последствия для разных политических участников."],
["Афины, Спарта и ограниченная демократия","V век до н. э.","Кто был включён в афинскую демократию и кто оставался за её пределами?","Афинские граждане-мужчины участвовали в народном собрании и судах, а Спарта имела иной общественный и военный порядок. Рабство, исключение женщин из формального гражданства и положение метеков показывают, что античная демократия не была всеобщим равноправием.","Гражданство в Афинах было ограничено происхождением и полом.","Спарта зависела от труда илотов и поддерживала военно ориентированные институты.","Политические права и экономическая власть распределялись неравномерно.","Athenian_democracy","Athenian agora assembly ancient Greece pottery","Почему слово «демократия» требует уточнения, если мы говорим об Афинах?","Определите группу граждан и группы исключённых из политического участия."],
["Идеи и театр Древней Греции","V–IV века до н. э.","Как философия и театр помогали обществу обсуждать власть и этику?","Греческая философия и драматургия ставили вопросы о справедливости, законе, долге и природе знания. Тексты дошли через сложную передачу рукописей, а сохранившиеся авторы не представляют всех жителей греческого мира.","Сократ известен главным образом через тексты других авторов.","Трагедии часто переосмысливали мифы для обсуждения современных общественных проблем.","Платон и Аристотель предлагали разные объяснения политики и знания.","Ancient_Greek_philosophy","ancient Greek theater amphitheatre Socrates Plato bust","Как литературный текст может свидетельствовать об общественных конфликтах, даже если сюжет мифологический?","Разделите художественную форму и исторический контекст создания."],
["Александр Македонский и эллинистический мир","IV–I века до н. э.","Почему завоевание не означает культурного единообразия?","Походы Александра разрушили державу Ахеменидов и создали пространство эллинистических царств. Греческий язык и городские формы распространились, но местные религии, языки и административные практики продолжали существовать и взаимодействовать.","Александр завоевал Персидскую империю в 330-х годах до н. э.","После его смерти империя распалась между диадохами.","Александрия в Египте стала крупным научным и торговым центром.","Alexander_the_Great","Alexander the Great mosaic Issus Alexandria map","Приведите один пример культурного обмена и один пример политической раздробленности после Александра.","Не отождествляйте распространение языка с исчезновением местных культур."],
["Практикум 5: сравнить полис и империю","Античность","Какая политическая система лучше решала разные задачи и для кого?","Полис и империя отличались масштабом, участием населения и механизмами управления. Сравнение требует уточнить критерий: военная мобилизация, локальная автономия, налогообложение или политическое участие. Нельзя оценивать весь античный мир только по современному идеалу демократии.","Полис мог предоставлять часть граждан прямое участие, но исключать других.","Империи управляли территориями через многоуровневые структуры.","Обе системы зависели от принуждения и неравного распределения ресурсов.","Classical_antiquity","ancient Greece polis Persian Empire map","Сформулируйте сравнительный тезис об одном сходстве и двух различиях.","Назовите критерий сравнения и используйте конкретные примеры."]
]],
["Рим: республика, империя и трансформация","Почему Рим расширился, изменился и распался на разные политические миры?","Власть, право и интеграция",[["Республика","Политическая система без наследственного монарха; реальное участие может быть ограничено."],["Патронат","Отношения взаимных услуг между социально неравными сторонами."],["Романизация","Изменение практик и институтов в римских провинциях; не обязательно полное культурное замещение."]],"https://openstax.org/books/world-history-volume-1/pages/7-introduction","Римская история демонстрирует связь между военной экспансией, институтами, социальным неравенством и политическими кризисами. Республика создала систему выборных магистратур и сената, но рост территории и богатства изменил баланс сил. Империя интегрировала регионы дорогами, правом, армией и гражданством, однако региональные различия сохранялись. Западная имперская власть исчезла в V веке, а восточная продолжилась в Византии.","Карта дорог и городов часто объясняет римское влияние не хуже списка императоров: инфраструктура связывала торговлю, армию и управление.",[
["Римская республика и её институты","509–27 годы до н. э.","Как республиканские институты распределяли власть — и кого они исключали?","Рим сочетал консулов, сенат, народные собрания и сложные формы гражданства. Эти институты ограничивали некоторых должностных лиц, но политическое влияние было неравномерным, а женщины и рабы не обладали равным гражданским статусом.","Консулы занимали высшие ежегодные магистратуры.","Плебеи боролись за политические права в течение нескольких столетий.","Республиканская конституция была совокупностью практик, а не единого письменного документа.","Roman_Republic","Roman Forum republican Rome senate ruins","Почему формальное наличие собраний не обязательно означает равное политическое влияние?","Сопоставьте институт и реальные социальные ограничения."],
["Завоевания, рабство и социальный конфликт","III–I века до н. э.","Как военная экспансия изменила римскую экономику и политику?","Завоевания привозили богатство, рабов и новые земли, усиливая элиты, но создавали напряжение вокруг землевладения, долгов и военной службы. Реформы Гракхов и гражданские конфликты показывают, как социальные проблемы могли перерастать в институциональный кризис.","Пунические войны усилили римское господство в западном Средиземноморье.","Рабский труд был важен в сельском хозяйстве и домашних хозяйствах, но не единственным типом труда.","Попытки земельных реформ столкнулись с сопротивлением влиятельных групп.","Roman_expansion","Roman legions Punic Wars archaeological relief","Постройте цепочку от завоевания к внутреннему политическому конфликту.","Укажите посредующие механизмы: земля, богатство, армия, гражданство."],
["Август и становление империи","27 год до н. э. — I век н. э.","Как Август сосредоточил власть, сохранив республиканские формы?","После гражданских войн Август создал устойчивую систему единоличного руководства, сохраняя многие республиканские названия и должности. Это позволило представить новый порядок как восстановление, хотя ключевые ресурсы армии и назначения зависели от принцепса.","Август получил титул принцепса и доминировал в политике.","Провинциальное управление и армия были перестроены.","Имперская идеология изображала власть Августа как восстановление мира и традиций.","Augustus","Augustus of Prima Porta statue","Какие признаки политической перемены могут скрываться за сохранением старых институтов и названий?","Отличите формальные учреждения от фактического распределения власти."],
["Римская повседневность, право и инфраструктура","I–II века н. э.","Что помогало интегрировать огромную империю?","Дороги, порты, города, армия, право и гражданство связывали регионы, но жизнь отличалась по богатству, правовому статусу, гендеру и местным традициям. Археология городов и бытовых предметов помогает выйти за рамки официальных рассказов об императорах.","Римское гражданство постепенно расширялось и было предоставлено большинству свободных жителей империи в 212 году.","Города поддерживали рынки, суды и местное самоуправление в разных формах.","Римское право оказало длительное влияние на правовые традиции Европы и Средиземноморья.","Roman_Empire","Roman roads aqueduct Pompeii household artifacts","Какие источники лучше всего показывают повседневность простых людей, а не только элит?","Предложите материальный и письменный источник с обоснованием."],
["Римский мир и распространение христианства","I–IV века н. э.","Почему небольшое религиозное движение стало общественной силой?","Христианство распространялось через городские сети, общины, тексты и личные связи. Отношения с имперской властью менялись: от периодических преследований до императорского покровительства и институционализации церкви.","Ранние христианские общины существовали в разных провинциях.","Константин поддержал христианство в IV веке.","Христианизация была длительным процессом, а не мгновенным обращением всего населения.","Christianity_in_the_Roman_Empire","early Christian catacombs Constantine mosaic","Как изменение государственной политики могло повлиять на распространение религии?","Покажите роль институтов, сетей и индивидуальных общин."],
["Кризисы Западной империи и Византия","III–VI века и далее","Почему распад Западной империи не означает исчезновения римского мира?","Западная имперская власть ослабла в условиях военных и финансовых кризисов, внутренних конфликтов и изменений миграции и политических союзов. В Восточной Римской империи императорская администрация, города и римская идентичность продолжились столетиями; термин «Византия» появился позднее.","Западная имперская власть обычно датируется завершившейся в 476 году.","Восточная Римская империя продолжалась до захвата Константинополя в 1453 году.","Историки спорят о сочетании причин, а не сводят преобразование к одному вторжению.","Fall_of_the_Western_Roman_Empire","late Roman Empire map Byzantine Constantinople","Почему объяснение «Рим пал из-за варваров» неполно?","Добавьте внутренние факторы и сравните западную и восточную траектории."],
["Практикум 6: объяснить трансформацию Рима","Античность и раннее Средневековье","Как построить многопричинное объяснение политического изменения?","Используйте несколько факторов: институциональные конфликты, военные расходы, региональные различия, изменение налоговой базы, миграции и легитимность власти. Различайте повод, долгосрочные условия и последствия. Избегайте телеологического вывода, будто позднейшее европейское устройство было заранее предопределено.","Политическое изменение не имеет единственной универсальной причины.","Римские институты продолжили влиять на право и религию.","Региональные траектории после V века существенно различались.","Late_antiquity","Roman Empire map transformation late antiquity","Напишите тезис и два взаимосвязанных фактора изменения Западной империи.","Каждый фактор должен быть подтверждён фактом и объяснён."]
]],
["Южная и Юго-Восточная Азия","Как религия, торговля и государство формировали азиатские общества?","Религия, океанские сети, государства",[["Буддизм","Религиозная и философская традиция, возникшая в Южной Азии."],["Муссон","Сезонная смена ветров, важная для морского движения в Индийском океане."],["Культурная адаптация","Изменение идеи или практики при переходе в новый социальный контекст."]],"https://openstax.org/books/world-history-volume-1/pages/8-introduction","Южная Азия была пространством религиозного многообразия, крупных государств и интенсивной торговли. Буддизм, индуистские традиции и джайнизм развивались и взаимодействовали, а маршруты Индийского океана связывали Индию с Восточной Африкой, Аравией и Юго-Восточной Азией. Заимствование идей редко было простым копированием: местные правители и общины приспосабливали их к собственным условиям.","Проследите путь одной идеи: как она могла перейти вместе с торговцами, измениться при дворе и стать частью местного ритуала.",[
["Буддизм и джайнизм","VI–V века до н. э. и позднее","Почему новые религиозные движения привлекали последователей в древней Индии?","Буддизм и джайнизм возникали в среде интеллектуальных и социальных изменений, обсуждая страдание, действие, освобождение и этическую дисциплину. Их распространение зависело от монашеских общин, покровительства и торговых сетей.","Буддийская традиция связывает своё начало с учением Сиддхартхи Гаутамы.","Джайнизм подчёркивал ахимсу — принцип ненасилия.","Региональные школы и практики развивались на протяжении столетий.","Buddhism","Buddha statue Sanchi stupa Jain sculpture","Каким образом религиозная идея могла распространяться без централизованного государства?","Объясните роль общин, торговых путей и покровителей."],
["Ашока и Маурийская империя","IV–II века до н. э.","Как правитель может использовать религиозную этику для управления?","Империя Маурьев объединила большие части Южной Азии. Эдикты Ашоки после кровопролитной войны в Калинге подчёркивали дхамму, нравственное поведение и благополучие подданных; это важные царские заявления, но не полная запись повседневной политики.","Маурийская империя достигла крупного территориального масштаба при Ашоке.","Эдикты высекались на скалах и колоннах в разных частях империи.","Публичные надписи позволяют исследовать царскую идеологию и обращение к подданным.","Ashoka","Ashoka pillar edicts Sanchi stupa map Maurya","Что царские эдикты могут сказать о цели правителя и чего не доказывают о реальном поведении чиновников?","Отличите заявленную политику от проверяемого результата."],
["Гупты и образ «золотого века»","IV–VI века н. э.","Почему понятие «золотой век» требует уточнения?","При Гуптах развивались литература, математика, искусство и политические сети, но процветание не было одинаковым для всех регионов и групп населения. Позднейшие национальные рассказы могут идеализировать эпоху, поэтому нужны критерии: наука, экономика, военная сила или повседневное благополучие.","Десятичные позиционные способы вычисления развивались в Южной Азии.","Санскритская литература и скульптура имели важное влияние.","Политическая власть Гуптов не охватывала неизменно всю Индию.","Gupta_Empire","Gupta period sculpture Ajanta cave paintings","По каким измеримым критериям можно оценить утверждение о «золотом веке»?","Назовите критерии и отметьте, какие группы могут отсутствовать в источниках."],
["Индуистские традиции и региональное разнообразие","I тысячелетие до н. э. — I тысячелетие н. э.","Почему индуизм не следует представлять как единый неизменный набор правил?","Индуистские традиции складывались через тексты, ритуалы, философию, местные культы и социальные практики. Они отличались по регионам и эпохам, а взаимодействие с буддизмом, джайнизмом и политическими центрами меняло религиозную жизнь.","Ведийская традиция — один из важных, но не единственный источник индуистских практик.","Пуранические и бхактийские традиции развивались в разные периоды.","Социальные и религиозные категории менялись исторически.","Hinduism","Hindu temple sculpture ancient India","Как избежать анахронизма, изучая религиозные практики древности через современные категории?","Определите эпоху источника и сравните её с более поздними традициями."],
["Индийский океан и сила муссонов","I тысячелетие до н. э. — XV век","Почему морская торговля не была монополией европейцев?","Муссонные ветры создавали предсказуемые сезонные маршруты в Индийском океане. Купцы, моряки и порты Индии, Аравии, Восточной Африки и Юго-Восточной Азии обменивались тканями, специями, металлами, религиозными идеями и технологиями задолго до европейской океанской экспансии.","Морские маршруты опирались на сезонное знание ветров.","Портовые города зависели от посредников и региональных производственных сетей.","Торговля переносила культурные практики вместе с товарами и людьми.","Indian_Ocean_trade","Indian Ocean trade routes monsoon map dhow","Как сезонность ветров влияла на сроки, цены и организацию морской торговли?","Свяжите природный механизм с решениями торговцев."],
["Юго-Восточная Азия: Ангкор и морские государства","IX–XV века","Как местные общества присваивали идеи из Индии и Китая?","Кхмерская империя Ангкор, Шривиджая и другие государства развивались благодаря земледелию, портам, религиозным связям и политической организации. Индийские религиозные и письменные традиции адаптировались к местным практикам, а не просто заменяли их.","Ангкор-Ват был связан с индуистскими, а затем буддийскими традициями.","Шривиджая контролировала важные морские узлы Юго-Восточной Азии.","Власть зависела от воды, сельского хозяйства и сетей обмена.","Khmer_Empire","Angkor Wat temple aerial Southeast Asia map","Почему заимствование религии или архитектуры не означает полного культурного подчинения?","Укажите местную адаптацию и исторический контекст."],
["Практикум 7: сеть, а не изолированная цивилизация","Древняя и средневековая Азия","Как доказать, что торговля меняла религию, культуру и власть?","Сопоставьте порты, материальные предметы, надписи и религиозные центры. Связи доказываются не одним сходным изображением, а несколькими независимыми признаками контакта. Одновременно спрашивайте, кто контролировал обмен и чья работа делала торговлю возможной.","Порты связывали материковые государства и океанские сети.","Религиозные идеи распространялись через торговцев, монахов и элиты.","Культурное влияние всегда включало локальные изменения.","Indian_Ocean_trade","Indian Ocean medieval trade artifacts map","Постройте мини-аргумент о том, как торговля влияла на общество одного региона.","Укажите два свидетельства, причинный механизм и возможное альтернативное объяснение."]
]],
["Китай, Корея, Япония и степь","Как институты и технологии распространялись по Восточной Азии?","Государство, знания и региональные различия",[["Бюрократия","Управление через должностных лиц и установленные процедуры."],["Мандат Неба","Китайская концепция легитимности династии, допускавшая утрату власти."],["Степные общества","Мобильные общества Евразийской степи с разнообразными формами пастушества, власти и обмена."]],"https://openstax.org/books/world-history-volume-1/pages/9-introduction","Китайские династии создавали мощные административные системы, но государственные решения влияли на разные регионы по-разному. Конфуцианская этика и экзаменационные практики формировали чиновничество; технологические и торговые сети распространяли бумагу, печать и знания. Корея и Япония заимствовали элементы китайской письменности и политической культуры, приспосабливая их к собственным институтам. Степные народы Евразии были партнёрами и соперниками земледельческих государств.","Спросите о любом заимствовании: что именно переняли, что изменили и какие местные обстоятельства остались другими?",[
["Цинь и объединение Китая","221 год до н. э.","Почему централизация Цинь усилила государство и вызвала сопротивление?","Цинь Шихуанди объединил соперничающие царства, стандартизировал меры и письмо, усилил администрацию и крупные проекты. Жёсткие повинности и репрессии способствовали недовольству, а династия быстро пала после смерти первого императора.","Объединение произошло в 221 году до н. э.","Легизм подчёркивал закон, дисциплину и силу административного контроля.","Многие стандарты и идея единой империи пережили короткое правление Цинь.","Qin_dynasty","Terracotta Army Qin Shi Huang tomb","Какие преимущества и издержки централизации показаны на примере Цинь?","Сопоставьте управленческую эффективность и социальную цену."],
["Хань: конфуцианство и бюрократия","206 год до н. э. — 220 год н. э.","Как идеология и администрация укрепляли династическую власть?","Ханьская империя развивала бюрократию и связывала управление с конфуцианскими идеалами образования и нравственности. Династии нуждались также в армии, налогах и местных элитах; идеология не заменяла материальные ресурсы.","Хань расширила территорию и дипломатические контакты.","Конфуцианская мысль стала важным источником языка чиновничьей этики.","Имперское управление сочетало центр, провинции и местные семейные сети.","Han_dynasty","Han dynasty tomb figure Silk Road map","Почему государственная идеология редко объясняет устойчивость империи сама по себе?","Добавьте административные, экономические и военные факторы."],
["Шёлковые пути и глобальная связность","II век до н. э. — XV век","Как товары, люди и болезни перемещались через Евразию?","Шёлковые пути представляли собой сеть сухопутных и морских маршрутов, связывавших Китай, Центральную Азию, Ближний Восток и Средиземноморье. Торговля распространяла технологии и религии, но также способствовала перемещению эпидемий. Ни один народ не контролировал всю сеть непрерывно.","Караваны зависели от оазисов, политической безопасности и посредников.","Буддизм распространялся по Центральной и Восточной Азии через разные сети.","Обмен мог иметь как положительные, так и разрушительные последствия.","Silk_Road","Silk Road historical map caravanserai","Объясните два разных последствия одного и того же торгового контакта.","Используйте факты о товарах, идеях или болезнях и покажите механизм."],
["Степные общества: гунны, тюрки и кочевая политика","Античность — Средневековье","Почему кочевников нельзя описывать только как угрозу оседлым империям?","Степные общества развивали мобильное пастушество, военную организацию, торговлю и дипломатические союзы. Они могли совершать набеги, обеспечивать обмен и создавать собственные империи. Отношения с земледельческими государствами были переменными и включали конфликт и взаимозависимость.","Лошади и мобильность давали важные военные преимущества.","Кочевые элиты обменивались скотом, лошадьми и товарами с городами.","Термин «кочевник» скрывает разнообразие политических и хозяйственных систем.","Nomadic_empire","Eurasian steppe nomad horse historical map","Как одна и та же мобильность могла давать преимущество в войне и торговле?","Сравните два контекста использования одного ресурса."],
["Тан и Сун: города, технологии и обмен","VII–XIII века","Почему эпоху Сун связывают с экономическими и технологическими изменениями?","При Тан и Сун города, торговля, производство, печатные технологии и финансовые практики развивались в масштабах, важных для мировой истории. Однако экономические изменения не отменяли социальных и политических ограничений, а регионы империи развивались неодинаково.","Ксилография и позднее подвижные литеры расширяли производство текстов.","Китайская экономика включала крупные рынки, ремёсла и морскую торговлю.","Порох и компас развивались в конкретных военных и навигационных контекстах.","Song_dynasty","Song dynasty painting market city Chinese compass","Почему технология влияет на общество лишь вместе с рынками, знаниями и институтами?","Укажите цепочку от изобретения к распространению и последствиям."],
["Корея и Япония: выборочное заимствование","I тысячелетие — XV век","Как общества перенимали элементы китайской культуры, сохраняя отличия?","Корея и Япония заимствовали письменные формы, буддизм и административные практики через дипломатические и религиозные контакты. Эти элементы менялись в местных условиях. Историю региона важно не сводить к роли пассивного получателя китайских влияний.","Корейские государства развивали собственные политические традиции и металлургию.","Японский двор адаптировал китайские письменные и религиозные практики.","Самурайские институты складывались в особом японском политическом контексте.","History_of_Korea","Gyeongbokgung palace Japanese samurai armor historical","Какие вопросы помогают отличить культурный обмен от простого копирования?","Назовите заимствованный элемент и местное изменение."],
["Практикум 8: государство и инновации в Восточной Азии","Древность — Средневековье","Как сравнивать государственные модели без идеи о неизбежном прогрессе?","Сравните Цинь, Хань, Тан и Сун по управлению, экономике, технологии и отношениям с соседями. Историческое объяснение должно показать не только успешные нововведения, но и пределы власти, социальную цену и причины изменения институтов.","Централизация меняла возможности государства собирать ресурсы.","Инновации распространялись через институты, торговлю и практику.","Системы власти адаптировались под региональные кризисы.","History_of_China","ancient China dynasty timeline map","Напишите тезис о том, почему одна китайская династия укрепляла институты, а другая сталкивалась с кризисом.","Используйте минимум два фактора и избегайте единственной причины."]
]],
["Африка до 1500 года","Как африканские общества строили государства и связывались с миром?","Торговля, религия, государственность",[["Транссахарская торговля","Сеть маршрутов через Сахару, соединявшая Северную и Западную Африку."],["Суахилийский мир","Портовые общества восточноафриканского побережья, связанные с Индийским океаном."],["Археологический источник","Материальный след прошлого, который требует контекста и интерпретации."]],"https://openstax.org/books/world-history-volume-1/pages/10-introduction","История Африки включает древние государства Нила, торговые империи Западной Африки, города побережья Индийского океана и многочисленные локальные общества. Сахара была не абсолютной стеной, а сложным пространством обмена, зависевшим от караванов, верблюдов и оазисов. Торговля золотом, солью, тканями и людьми меняла политическую власть, но не определяла всё общество одной экономической связью.","Сравните карту караванных путей с картой портов: по ней можно увидеть, как внутренние районы были включены в мировые связи.",[
["Нубия, Куш и Аксум","Древность — VII век","Как африканские государства формировали связи с Нилом, Красным морем и Средиземноморьем?","Куш и Аксум были самостоятельными центрами власти и обмена. Аксум контролировал важные маршруты Красного моря, использовал монету и оставил надписи; связи с Римом, Аравией и другими регионами влияли на религию и торговлю.","Аксум развивался на территории современной Эфиопии и Эритреи.","Аксумские правители использовали монеты и надписи для демонстрации власти.","Христианство стало важной традицией Аксумского царства в IV веке.","Kingdom_of_Aksum","Aksum obelisk stela Ethiopia","Какие независимые свидетельства показывают, что Аксум участвовал в международной торговле?","Сопоставьте монеты, географию, надписи и археологические данные."],
["Гана и транссахарские маршруты","Около VIII–XIII веков","Как торговля золотом и солью усиливала власть Западной Африки?","Политические центры Западной Африки получали влияние благодаря контролю над маршрутами, рынками и сбором платежей. Сахара связывала разные климатические зоны, а купцы и посредники обеспечивали движение товаров. Письменные внешние описания нужно читать с учётом взглядов их авторов.","Гана была предшественником, но не тождественна современной стране Гане.","Верблюжий транспорт расширил возможности длительных пересечений пустыни.","Торговля золотом не означает, что вся экономика региона зависела только от золота.","Ghana_Empire","trans-Saharan trade camel caravan map Ghana Empire","Почему контроль над узлом торговли может усилить правителя даже без владения всеми ресурсами?","Объясните роль посредничества и налогообложения."],
["Мали, Манса Муса и Тимбукту","XIII–XV века","Как образование и торговля поддерживали престиж империи Мали?","Империя Мали развивалась в сети торговли золотом и другими товарами; исламские учёные и города стали важными центрами образования. Паломничество Мансы Мусы в 1324 году известно из письменных традиций, но не должно превращаться в карикатурный рассказ только о богатстве.","Мали связывала торговые и политические сети Западной Африки.","Тимбукту и другие города были центрами учёности и рукописной культуры.","Ислам распространялся через торговлю, учёных и правителей, взаимодействуя с местными традициями.","Mali_Empire","Timbuktu Sankore mosque medieval manuscript","Как город может усиливать империю не только как рынок, но и как центр знаний?","Используйте сведения об институтах образования, религии и обмена."],
["Суахилийские города и Индийский океан","IX–XV века","Почему восточноафриканское побережье было частью океанского мира?","Килва, Момбаса, Малинди и другие города участвовали в торговле Индийского океана. Суахилийские общества сочетали местные африканские традиции с исламом, торговыми контактами и архитектурными заимствованиями. Их история — пример активного участия Африки в морских сетях.","Суахилийские языки имеют основу банту и многочисленные заимствования.","Портовые города обменивались золотом, слоновой костью, тканями, керамикой и другими товарами.","Кораллово-каменная архитектура свидетельствует о местных строительных навыках и международных контактах.","Swahili_coast","Kilwa Kisiwani ruins Swahili coast map","Как архитектура и бытовые предметы могут показывать одновременно местные традиции и глобальные контакты?","Назовите по одному свидетельству каждого типа."],
["Эфиопские христианские традиции и Лалибэла","Средневековье","Как география и религия формировали региональные государства?","Эфиопские государства развивали христианские институты, письменные традиции и связи с Красным морем и соседними регионами. Церкви Лалибэлы показывают крупные инженерные и религиозные проекты, но требуют контекста о труде, власти и местной общине.","Геэз сохранялся как язык церковной литературы.","Высеченные в скале церкви Лалибэлы связаны с христианским паломничеством.","Эфиопская история развивалась в постоянном взаимодействии с соседями, а не в изоляции.","Ethiopian_Orthodox_Tewahedo_Church","Lalibela rock-hewn churches Ethiopia","Какие сведения монументальная религиозная архитектура даёт о власти и коллективном труде?","Отделите прямые признаки организации от предположений о конкретных рабочих."],
["Бенин, Великий Зимбабве и другие центры","XI–XV века","Что разрушает представление об Африке как о континенте без крупных городов?","В разных регионах Африки существовали города, ремесленные центры и сложные политические системы. Великий Зимбабве связан с каменной архитектурой и региональной торговлей; Бенин известен городской организацией и художественными традициями. Эти примеры показывают разнообразие, а не единую модель континента.","Великий Зимбабве был центром внутренней торговли и скотоводства.","Бенинские бронзы — высококачественные произведения искусства и важные исторические источники.","Колониальные теории нередко отрицали африканское авторство сложных сооружений без оснований.","Great_Zimbabwe","Great Zimbabwe stone ruins Benin bronzes museum","Как археологические находки опровергают старые предубеждения об исторических обществах?","Используйте конкретные материальные доказательства и анализируйте историю самой интерпретации."],
["Практикум 9: Африка и глобальные сети","До 1500 года","Как показать взаимосвязь регионов без европоцентричной схемы?","Сопоставьте караванные пути, порты, надписи, монеты, рукописи и архитектуру. Африканские общества не были единым целым, но многие из них участвовали в обмене через Сахару, Красное море и Индийский океан. Важны и торговые связи, и местное производство, и внутренние конфликты.","Сахара связывала, но одновременно усложняла обмен.","Океанские порты поддерживали связи Африки с Азией.","Региональные государства имели различные политические и культурные траектории.","African_history","Africa medieval trade routes Mali Aksum Swahili map","Напишите тезис о роли одного африканского торгового центра до 1500 года.","Используйте два источника или типа данных и объясните ограничения."]
]],
["Америки до европейского завоевания","Как общества Америк строили города, государства и региональные системы?","Разнообразие обществ Америк",[["Мезоамерика","Культурно-исторический регион Центральной Америки и юга Мексики."],["Андские цивилизации","Разнообразные общества западной части Южной Америки, включая инков."],["Колумбов обмен","Перенос растений, животных, людей, болезней и технологий после контакта континентов."]],"https://openstax.org/books/world-history-volume-1/pages/11-introduction","До прибытия европейцев в Америке существовали земледельческие общества, города, торговые сети, государства и региональные союзы. Маис, картофель и другие культуры позволяли поддерживать большие населённые центры; условия Мезоамерики, Анд и Северной Америки создавали разные пути развития. Европейское завоевание привело к катастрофическим демографическим изменениям, но местные народы не были пассивными наблюдателями собственной истории.","На карте отметьте высокогорные Анды, тропические леса, долины и побережья. Разные условия помогали развивать разные формы земледелия и власти.",[
["Майя: города, календарь и письмо","I тысячелетие до н. э. — XVI век","Почему цивилизацию майя нельзя описывать как единую империю?","Майя создавали множество городских государств с календарями, письменностью, монументальной архитектурой и политическими соперничествами. Их история включает периоды роста, войны и изменения поселений; регион не исчез внезапно, а майя продолжают существовать сегодня.","Майя создали одну из развитых письменных систем доколумбовой Америки.","Города соперничали, заключали союзы и меняли политический вес.","Крах части низменных городов около IX века имел сложные экологические и политические причины.","Maya_civilization","Maya glyphs Tikal pyramid stela","Как археологи и дешифровка письма меняют понимание общества майя?","Укажите, что дают надписи и какие вопросы остаются открытыми."],
["Ацтеки и Теночтитлан","XIV–XVI века","Как городская организация и союзы помогли создать империю ацтеков?","Мехика основали Теночтитлан на островах озера Тескоко и стали ядром Тройственного союза. Империя собирала дань с подчинённых обществ, но не контролировала все регионы одинаково; недовольство подчинённых групп повлияло на ход испанского завоевания.","Чинампы повышали продуктивность земледелия вокруг столицы.","Имперская дань поддерживала город и элиту.","Испанцы воспользовались местными союзами и внутренними конфликтами в 1519–1521 годах.","Aztec","Tenochtitlan reconstruction Aztec codex","Почему крупная империя могла быть военной сильной, но политически уязвимой?","Объясните роль дани, союзов и сопротивления."],
["Инки и управление Андами","XV–XVI века","Как инки управляли территориями с разным климатом и ландшафтом?","Империя инков соединяла горные и прибрежные регионы сетью дорог, административных центров, складов и трудовых повинностей. Кипу использовались для записи информации, хотя возможности их расшифровки и интерпретации ограничены. Завоевание Писарро опиралось и на внутренний кризис после гражданской войны.","Куско был политическим центром инкской державы.","Мит'а организовывала трудовые обязательства и существовала в разных формах до и после завоевания.","Дороги и склады поддерживали перемещение армии и ресурсов через Анды.","Inca_Empire","Inca road system Machu Picchu quipu","Как дороги и склады позволяли государству управлять сложным горным ландшафтом?","Покажите связь инфраструктуры и власти."],
["Северная Америка: разные пути развития","До 1500 года","Почему нельзя свести коренные народы Северной Америки к одной культуре?","В Северной Америке существовали разнообразные охотничьи, земледельческие, речные и торговые общества. Миссисипская культура строила крупные центры вроде Кахокии; народы побережий и равнин имели иные хозяйства и политические формы.","Кахокия была крупным центром Миссисипской культуры.","Кукуруза меняла экономику и расселение в ряде регионов.","Торговые и политические сети соединяли общества на больших расстояниях.","Mississippian_culture","Cahokia mounds archaeological site","Как археология показывает сложность общества, даже если нет письменной хроники?","Назовите признаки специализации, обмена и коллективной организации."],
["Земледелие, маис и городские системы","До 1500 года","Как одна культура растения могла изменить демографию и общество?","Маис и другие культуры поддерживали рост населения и разнообразные формы земледелия в Америке. Однако технология не объясняет автоматически политическую сложность: требовались обмен, знания, организация труда и взаимодействие с окружающей средой.","Маис был важным продуктом для Мезоамерики и многих других регионов.","Картофель и другие андские культуры были адаптированы к разным высотным зонам.","Земледельческие общества сочетали разные техники и не имели единой модели поселений.","Maize","maize corn ancient agriculture Americas","Постройте причинную цепочку от нового земледельческого продукта к изменению общества.","Избегайте объяснять сложное общество одной технологией."],
["Контакт 1492 года и последствия завоевания","XV–XVII века","Почему встреча континентов была одновременно обменом и катастрофой?","После 1492 года перемещение болезней, растений, животных, людей и ресурсов радикально изменило Атлантический мир. Эпидемии вызвали огромные потери среди коренных народов; завоевание, принудительный труд и рабство укрепили колониальные системы. Местные сообщества сопротивлялись и адаптировались разными способами.","Оспа и другие болезни сыграли важную роль в демографическом кризисе.","Колумбов обмен изменил сельское хозяйство Евразии, Африки и Америк.","Колонизация сопровождалась как насилием, так и сложными формами культурного взаимодействия.","Columbian_exchange","Columbian exchange map crop animals indigenous codex","Почему термин «обмен» может скрывать резкое неравенство участников?","Сравните движения биологических видов с политикой завоевания и принудительным трудом."],
["Практикум 10: сравнить доколумбовы общества","До XVI века","Как сравнить майя, ацтеков и инков без иерархии «более/менее развитые»?","Сравните источники власти, хозяйство, городскую организацию, инфраструктуру и письменные или учётные системы. Разные общества решали разные задачи в разных природных условиях. «Развитие» не является одной линейкой, а колониальные описания часто недооценивали сложность местных систем.","Майя образовывали сеть городских государств.","Ацтекская власть опиралась на дань и военную гегемонию.","Инкская администрация использовала дороги, склады и трудовые обязательства.","Pre-Columbian_era","Maya Aztec Inca comparative map artifacts","Сформулируйте один критерий сходства и два различия между двумя обществами.","Используйте конкретные примеры и отметьте, что источники сохранились неравномерно."]
]],
["Европа, Византия и исламский мир","Как религия, торговля и политические институты связывали Средневековье?","Средневековые общества и обмен",[["Халифат","Политическое образование, возглавляемое халифом; его формы менялись со временем."],["Феодальные отношения","Разные системы земли, военной службы и зависимости, не одинаковые во всей Европе."],["Схоластика","Средневековая интеллектуальная традиция, сочетавшая философию и теологию."]],"https://openstax.org/books/world-history-volume-1/pages/12-introduction","Средневековье было периодом глубоких изменений, а не единым «тёмным веком». Восточная Римская империя сохраняла города и бюрократию; исламские государства создавали центры науки и торговли; европейские общества развивали королевства, церкви и городские общины. Обмен знаниями происходил через переводы, рынки, дипломатические связи и передвижение людей, часто через несколько языков и посредников.","Выберите одну технологию или идею и проследите, как она могла пройти через несколько культур, прежде чем попасть в новый регион.",[
["Византия и Константинополь","IV–XV века","Почему Восточная Римская империя сохранилась надолго после падения Рима на Западе?","Восточная империя сохраняла налоговые, военные и административные институты, сильную столицу и доступ к ресурсам восточного Средиземноморья. Её история включала кризисы и территориальные потери, но также реформы, дипломатическое маневрирование и культурное развитие.","Константинополь занимал стратегическое положение между морями и континентами.","Юстиниан I провёл кодификацию римского права в VI веке.","Византия была продолжением римской политической традиции, хотя её язык и культура менялись.","Byzantine_Empire","Hagia Sophia Byzantine mosaic Constantinople map","Какие факторы объясняют длительность государства лучше, чем утверждение о «сильной столице» в одиночку?","Сочетайте географию, ресурсы, институты и дипломатию."],
["Возникновение ислама и ранние халифаты","VII–VIII века","Как ислам изменил политические и культурные связи Западной Азии?","Ислам возник в Аравии в VII веке, а после смерти Мухаммеда арабские завоевания создали крупные политические образования. Управление включало разные языковые, религиозные и правовые традиции; распространение ислама было длительным процессом и не сводилось к завоеванию.","Мекка и Медина — ключевые места ранней исламской истории.","Умма обозначает сообщество верующих, но политическая организация мусульман менялась.","Ранние халифаты включили территории бывшей Византии и Сасанидов.","Early_caliphates","early Islamic architecture Dome of the Rock manuscript","Почему завоевание территории и изменение религиозной принадлежности — разные процессы?","Разведите политическую власть, практики населения и изменение во времени."],
["Аббасиды, наука и переводческие движения","VIII–XIII века","Как центры знания объединяли разные культурные традиции?","При Аббасидах и в других центрах исламского мира развивались математика, медицина, философия и астрономия. Учёные работали с греческими, персидскими, индийскими и другими текстами; перевод и критика знаний были активным интеллектуальным процессом, а не простым копированием.","Багдад стал важным центром книжной культуры и управления.","Математические и астрономические знания перемещались через несколько языковых традиций.","Научное развитие поддерживали дворы, медресе, библиотеки и торговые связи в разных формах.","Islamic_Golden_Age","House of Wisdom Baghdad medieval manuscript astrolabe","Как переводы и межкультурные сети могут создавать новое знание, а не просто сохранять старое?","Приведите механизм изменения или сочетания идей."],
["Средневековая Европа: земля, церковь и власть","V–XIII века","Почему европейское Средневековье нельзя описать одной «феодальной системой»?","В Европе существовали разные формы землевладения, вассалитета, крестьянских обязанностей, королевской и церковной власти. Эти институты менялись по времени и региону; города, торговля и денежные отношения усложняли представление об одном неизменном феодальном порядке.","Королевская власть часто зависела от местных элит и церковных институтов.","Крестьяне имели различные формы зависимости и прав.","Монастыри сохраняли и производили знания, управляли землёй и участвовали в экономике.","Feudalism","medieval European manor castle manuscript","Почему историки осторожно используют понятие «феодализм» как универсальное объяснение?","Покажите региональные различия и изменения во времени."],
["Крестовые походы: разные перспективы","XI–XIII века","Почему нельзя описывать крестовые походы только глазами одной стороны?","Крестовые походы были религиозными, политическими и социальными предприятиями, связанными с папской властью, землёй, военной знатью и отношениями между религиозными обществами. Латинские, византийские, мусульманские и местные христианские источники рассказывали о событиях по-разному.","Первый крестовый поход начался в 1096 году.","Захват Константинополя крестоносцами в 1204 году углубил раскол между латинским Западом и Византией.","Торговля и культурный контакт сопровождались насилием и враждой.","Crusades","Crusades medieval manuscript map Jerusalem","Как определить, что рассказ участника крестового похода подчёркивает или скрывает?","Укажите аудиторию, цель и отличия другого источника."],
["Города, университеты и Чёрная смерть","XI–XIV века","Как городская жизнь и эпидемии меняли средневековое общество?","Рост городов и торговли создавал новые профессиональные группы и образовательные институты. Чёрная смерть середины XIV века вызвала огромную смертность и изменила рынки труда, религиозную жизнь и отношения между землевладельцами и крестьянами, хотя последствия различались по регионам.","Университеты формировались в нескольких европейских городах.","Чума распространилась по торговым сетям в 1340-х годах.","Демографический кризис мог усиливать работников там, где рабочая сила стала дефицитной.","Black_Death","Black Death medieval manuscript plague doctors","Почему одинаковая эпидемия могла иметь разные последствия в разных экономических системах?","Свяжите демографию с институтами труда и управления."],
["Практикум 11: сравнить три средневековых мира","Средневековье","Как сопоставлять Византию, исламские государства и Европу без шкалы «цивилизованности»?","Сравните бюрократию, религиозные институты, города, военную организацию и обмен знаниями. Разные общества испытывали влияние античного наследия и внешних контактов, но переосмысляли их по-разному. Исторический анализ ищет конкретные механизмы, а не вечное противопоставление Востока и Запада.","Византия продолжала римскую административную традицию.","Исламский мир объединял многочисленные языки и научные центры.","Европейские общества развивали разные комбинации королевской, церковной и городской власти.","Medieval_history","medieval Europe Byzantine Islamic world map","Напишите сравнительный ответ по двум критериям с примерами из двух регионов.","Тезис должен отвечать на вопрос, а не просто перечислять особенности."]
]],
["Монголы, позднее Средневековье и глобальные связи","Как степная экспансия изменила Евразию и почему империи меняются?","Завоевание, обмен и кризис",[["Ярлык","Документ, подтверждавший право князя на определённое правление в ордынско-русском контексте."],["Караванный путь","Маршрут обмена товарами, знаниями и людьми, поддерживаемый сетью посредников."],["Чёрная смерть","Пандемия чумы XIV века с тяжёлыми демографическими последствиями."]],"https://openstax.org/books/world-history-volume-1/pages/13-introduction","Монгольские завоевания разрушали города и политические структуры, но затем создали новые имперские сети, в которых люди, товары и технологии перемещались на большие расстояния. Эти связи были неодинаково безопасными и не превращали всю Евразию в единую мирную систему. Позднее распад монгольских государств, эпидемии, войны и новые центры власти изменили маршруты и региональные балансы.","Рассмотрите одну дорогу и спросите, кто мог по ней безопасно перемещаться, кто взимал пошлину, и как война меняла торговлю.",[
["Чингисхан и создание Монгольской империи","Конец XII — XIII век","Какие факторы помогли монголам объединить огромные пространства?","Монгольская экспансия опиралась на военную мобильность, организацию, дисциплину, дипломатию и способность использовать специалистов покорённых обществ. Завоевания сопровождались разрушениями и массовыми потерями; позднейшая торговая интеграция не отменяет насилия, с помощью которого создавалась империя.","Чингисхан объединил монгольские группы и начал крупные завоевания в начале XIII века.","Монгольские армии применяли разведку, мобильность и адаптацию к разным противникам.","После завоеваний местные администраторы и ремесленники часто продолжали обслуживать государство.","Mongol_Empire","Mongol Empire map Genghis Khan historical illustration","Как мобильность и организационные навыки усиливали армию, но не объясняли все её победы?","Включите логистику, дипломатию и особенности противников."],
["Завоевание Руси и Ордынская власть","XIII–XV века","Как монгольское завоевание изменило княжеские институты?","Походы Батыя нанесли тяжёлый ущерб многим русским землям. В последующие века отношения с Ордой включали дань, ярлыки, дипломатические поездки и борьбу князей за преимущества. Разные территории переживали зависимость и восстановление неодинаково.","Походы 1237–1240 годов разорили ряд городов Руси.","Князья получали ярлыки на княжение и участвовали в системе ордынской власти.","Зависимость сочетала принуждение и политические переговоры.","Mongol_invasion_of_Kievan_Rus","Mongol invasion Rus map medieval manuscript","Почему неверно сводить все последствия ордынской власти к одному политическому результату?","Покажите различия по регионам и временным периодам."],
["Монгольский обмен и маршруты Евразии","XIII–XIV века","Как имперская инфраструктура влияла на распространение технологий и болезней?","Монгольские государства в отдельные периоды поддерживали перемещения послов, купцов и ремесленников. Безопасность была переменной, а торговые сети переносили не только товары, но и эпидемии. Историки обсуждают, как именно связность повлияла на скорость распространения чумы.","Почтово-дорожные системы помогали передавать приказы.","Торговля расширяла движение технологий и религий между регионами.","Чума распространялась сложными маршрутами через торговлю, людей и животных.","Pax_Mongolica","Mongol Empire Silk Road map caravanserai","Почему рост связности может одновременно усиливать богатство и эпидемиологический риск?","Объясните один положительный и один отрицательный механизм."],
["Кризис и распад монгольских государств","XIV–XV века","Почему крупные империи распадаются на отдельные политические центры?","После периода экспансии монгольские государства испытывали династические конфликты, региональные интересы, финансовые трудности и изменения военной силы. Распад не означал исчезновение всех связей: многие институты и торговые маршруты продолжали существовать.","Золотая Орда была одним из нескольких крупных государств-преемников.","Юань в Китае была свергнута Мин в 1368 году.","Политический распад мог усиливать автономию региональных элит и менять маршруты торговли.","Mongol_Empire","Golden Horde map Yuan dynasty historical map","Сравните два фактора внутреннего кризиса империи и один внешний фактор.","Объясните взаимодействие причин, а не перечисление."],
["Чёрная смерть: распространение и общество","1340-е — XV век","Как пандемия меняла экономику, религиозную жизнь и власть?","Чума резко сократила население многих регионов Евразии и Северной Африки. Дефицит труда мог изменить заработки и крепостные отношения; страх способствовал религиозным и социальным реакциям, включая преследования меньшинств. Последствия зависели от институтов и местных решений.","Пандемия достигла Средиземноморья в 1347 году и распространилась далее.","Население пострадало неравномерно по регионам и социальным группам.","Экономические и культурные последствия растянулись на десятилетия.","Black_Death","Black Death map medieval plague cemetery archaeology","Как демографический шок может изменить рынок труда и политические отношения?","Покажите цепочку демография → труд → институты."],
["Минский Китай, Османы и позднесредневековые центры","XIV–XV века","Почему после монгольской эпохи мир не вернулся к прежней изоляции?","Новые династии и империи восстанавливали или перестраивали институты, продолжая обмен между регионами. Минский Китай, Османское государство и другие центры развивались в сложных сетях торговли, войны и дипломатии перед ранним Новым временем.","Мин свергла Юань и восстановила китайскую династическую власть.","Османы захватили Константинополь в 1453 году.","Смена правителей не означала полного разрыва торговых и культурных связей.","Ming_dynasty","Ming dynasty Forbidden City Ottoman Constantinople map","Как политический переворот может менять институты, сохраняя часть экономических связей?","Укажите одновременно преемственность и перемены."],
["Практикум 12: причинность и непредвиденные последствия","XIII–XV века","Как оценивать историческое событие, последствия которого оказались неоднозначными?","Используйте монгольскую экспансию и чуму, чтобы отличать намерения от результатов. Исторические процессы дают непредвиденные последствия: развитие сетей может ускорять торговлю и переносить болезни, а завоевание разрушает одни центры и создаёт другие. Избегайте объяснять всё одной неизбежной линией.","Завоевания создавали новые политические границы и сети контактов.","Эпидемии меняли общества через демографию и институциональную реакцию.","Один процесс может иметь противоположные последствия в разных регионах.","Late_medieval_period","Mongol trade route plague medieval Eurasia map","Составьте объяснение по схеме причина — механизм — последствия — различия регионов.","Проверьте, что у каждого звена есть доказательство или явно обозначенная гипотеза."]
]],
["Русь, Литва и возвышение Москвы","Почему разные земли восточной Европы выбрали различные политические траектории?","Княжества, зависимость и централизация",[["Летопись","Запись событий по годам, созданная и переписанная в конкретной традиции."],["Вече","Собрание горожан или политического сообщества в некоторых средневековых славянских землях."],["Централизация","Сосредоточение политических решений и ресурсов у центральной власти."]],"https://openstax.org/books/world-history-volume-1/pages/14-introduction","История Руси развивалась на пересечении Балтики, степи, Византии и Центральной Европы. Киевская Русь была политическим образованием с меняющимися центрами; после раздробленности разные территории вошли в различные политические объединения, включая Великое княжество Литовское. Возвышение Москвы было результатом конкуренции, династической политики и ресурсных стратегий, а не заранее предопределённым исходом.","На карте сравните речные маршруты торговли с границами княжеств: экономические связи не всегда совпадали с политическими.",[
["Киевская Русь и торговые сети","IX–XIII века","Как речная торговля и княжеская политика формировали раннюю Русь?","Русь формировалась из местных обществ и торгово-политических контактов Балтики, Днепра, Византии и степи. Княжеская власть развивалась через династические связи, войну, дань и торговлю. Летописные рассказы записывались позже описываемых событий и требуют сопоставления с археологией и внешними источниками.","Киев был важным центром благодаря положению на торговых маршрутах.","Варяги участвовали в ранних сетях власти и торговли, но не объясняют всё формирование Руси.","Русь была многосоставным политическим пространством с разными локальными интересами.","Kievan_Rus","Kievan Rus map Saint Sophia Kyiv medieval manuscript","Почему нельзя объяснить образование Руси только ролью варягов или только местных славян?","Постройте многофакторное объяснение с разными типами свидетельств."],
["Крещение Руси и связи с Византией","Конец X века","Почему христианизация была одновременно религиозным и политическим процессом?","Крещение князя Владимира и последующее распространение христианства укрепили дипломатические и культурные связи с Византией. Религиозные изменения затрагивали письменность, искусство, право и власть, но происходили неодновременно, взаимодействуя с более ранними традициями.","988 год считается традиционной датой крещения Руси.","Церковь усилила письменную культуру и международные связи княжеской власти.","Официальное принятие религии не означает мгновенного изменения всех местных практик.","Christianization_of_Kievan_Rus","Saint Sophia Kyiv mosaics Byzantine Rus church","Как религиозная реформа может изменить государственные институты и внешнюю политику?","Укажите хотя бы два механизма и одну границу быстрых изменений."],
["Княжеская раздробленность и Новгород","XII–XIII века","Почему разные русские земли развивали разные формы власти?","Соперничество княжеских династий, региональные ресурсы и торговые интересы формировали политическое разнообразие. Новгород опирался на торговые элиты и вечевые практики, а северо-восточные княжества развивали собственные модели княжеской власти.","Новгород был связан с торговлей Балтийского региона.","Вече не следует без оговорок считать современной демократией.","Локальные институты отражали баланс элит, города и княжеских интересов.","Novgorod_Republic","Novgorod Kremlin medieval icon map","Как торговые интересы могли влиять на политические институты города?","Объясните связь экономики с участием элит и формами власти."],
["Великое княжество Литовское и восточноевропейский мир","XIII–XVI века","Почему часть земель бывшей Руси развивалась за пределами Московского государства?","Великое княжество Литовское расширялось на значительные восточнославянские территории и включало разнообразные языки, религии и правовые традиции. История региона показывает, что объединение земель могло происходить в разных государствах и не сводилось к единственному центру.","Литовское государство было многонациональным и многоконфессиональным.","Рутенский язык и местные правовые практики сохраняли значение.","Политические союзы и унии меняли региональную карту.","Grand_Duchy_of_Lithuania","Grand Duchy of Lithuania historical map medieval castle","Как изучение альтернативного политического центра меняет рассказ о «собирании Руси»?","Сопоставьте разные центры и их интересы без телеологии."],
["Москва, Орда и соперничество князей","XIII–XV века","Какие факторы помогли Москве усилиться?","Московские князья сочетали династические союзы, церковные связи, сбор ресурсов и дипломатические отношения с Ордой. Москва конкурировала с Тверью и другими центрами; результаты битв были важны, но политическая централизация шла длительно и не отменяла внешнюю зависимость сразу.","Иван Калита укрепил позиции Москвы в XIV веке.","Куликовская битва 1380 года имела символическое значение, но не завершила ордынскую зависимость.","Присоединение территорий шло через войну, выкупы, наследование и соглашения.","Grand_Duchy_of_Moscow","Moscow Kremlin medieval map Kulikovo battle painting","Почему Куликовскую битву недостаточно назвать единственной причиной возвышения Москвы?","Добавьте административные, экономические и династические факторы."],
["Иван III и создание более централизованного государства","XV — начало XVI века","Как менялась политическая власть при расширении Москвы?","Иван III расширял владения Москвы, ограничивал самостоятельность соперников и усиливал государственные претензии на суверенитет. Стояние на Угре 1480 года традиционно связывают с окончанием зависимости от Орды, но конкретные институциональные изменения были постепенными.","Новгород был присоединён к Москве в 1478 году.","Стояние на Угре произошло в 1480 году.","Символы византийского наследия и титулатура участвовали в легитимации власти.","Ivan_III","Ivan III Kremlin medieval Russia map","Какие признаки показывают изменение суверенитета, а какие относятся к позднейшей государственной памяти?","Разделите политическое событие и его ретроспективную символику."],
["Практикум 13: несколько историй Восточной Европы","IX–XVI века","Как писать об истории региона, где существовало несколько центров власти?","Сравните Киев, Новгород, Великое княжество Литовское и Москву по торговле, институтам, внешним связям и источникам. Историческое объяснение не должно превращать победивший центр в неизбежную цель прошлого. Рассмотрите альтернативные исходы и различия регионов.","Восточная Европа была политически многообразной.","Церковная, торговая и династическая связь не всегда совпадала с границей государства.","Источники разных традиций могут по-разному объяснять легитимность власти.","Eastern_Europe","medieval Eastern Europe Rus Lithuania Novgorod map","Напишите аргумент о том, почему возвышение Москвы было процессом, а не неизбежностью.","Добавьте альтернативный центр и свидетельство, поддерживающее сравнение."]
]],
["Мир 1400–1750: империи и новые связи","Почему раннее Новое время усилило океанскую торговлю, империи и культурные обмены?","Глобальные сети и преобразования",[["Колумбов обмен","Массовый обмен видами, людьми, болезнями и товарами между полушариями после 1492 года."],["Реформация","Религиозные движения XVI века, изменившие христианскую Европу."],["Меркантилизм","Экономические представления, связывавшие силу государства с контролем торговли и богатства."]],"https://openstax.org/books/world-history-volume-2/pages/1-introduction","После 1400 года мировые сети не возникли внезапно, но океанская экспансия усилила связность между континентами и изменила масштабы колониализма. Османская, Сефевидская и Могольская империи управляли большими территориями; Китай и Япония сохраняли самостоятельные траектории. Реформация, печать, научные изменения и государственная конкуренция влияли на религиозные и политические институты.","Спросите, кто контролирует морской путь, порт и источник сырья: технология плавания важна, но торговые сети зависят также от капитала, принуждения и государства.",[
["Ренессанс и гуманизм","XIV–XVI века","Как античное наследие переосмысливали художники и учёные?","Ренессанс включал новые подходы к образованию, искусству и текстам, опираясь на античные образцы и современную городскую культуру. Это был не одновременный переход всей Европы в «светлую эпоху», а регионально различный процесс, связанный с патронатом, торговлей и политической конкуренцией.","Гуманисты изучали и редактировали античные тексты.","Меценатство дворов, церкви и городских элит поддерживало искусство.","Ренессанс сосуществовал с религиозными традициями и социальными иерархиями.","Renaissance","Renaissance painting perspective Leonardo da Vinci","Как художественное изображение может отражать технологию, патронат и идеалы эпохи?","Свяжите конкретную визуальную деталь с контекстом создания."],
["Печать и Реформация","XV–XVI века","Почему печать изменила скорость распространения религиозных идей?","Печатные тексты помогали распространять религиозные споры и переводные Библии. Реформация возникла из сочетания богословских разногласий, политических интересов, церковных проблем и новых медиа. Она создала разные церкви и вызвала длительные конфликты.","Печатание с подвижными литерами в Европе связано с Иоганном Гутенбергом.","Реформация Мартина Лютера началась в 1517 году.","Политические правители по-разному использовали и ограничивали религиозные движения.","Protestant_Reformation","Gutenberg Bible Reformation pamphlet woodcut","Как технология распространения текста меняет политический и религиозный спор?","Покажите механизм распространения и роль покровителей или цензуры."],
["Османская, Сефевидская и Могольская империи","XV–XVIII века","Как империи управляли культурным и религиозным разнообразием?","Османы, Сефевиды и Великие Моголы использовали армии, налоги, бюрократию и сотрудничество с местными элитами. Религия была важна для легитимности, но политика варьировалась: империи включали множество языков и общин и меняли методы управления.","Османы захватили Константинополь в 1453 году.","Сефевиды укрепили шиитский ислам как государственную традицию Ирана.","При Акбаре Могольская империя экспериментировала с отношениями к различным религиозным общинам.","Early_modern_empires","Ottoman Topkapi Palace Safavid miniature Mughal Akbar painting","Почему религиозная политика империи могла меняться в зависимости от задачи правителя?","Сравните две империи и конкретные механизмы управления."],
["Китай Мин и Цин: государство и торговля","XIV–XVIII века","Как Китай сочетал бюрократическую традицию и мировую торговлю?","Мин восстановила династическую власть после Юань, а Цин создала многоэтничную империю. Государственная политика по отношению к морской торговле менялась, однако коммерческие сети продолжали связывать Китай с Азией, а позднее с океанским миром.","Флот Чжэн Хэ совершал крупные экспедиции в начале XV века.","Китай был важным производителем фарфора, шёлка и других товаров.","Маньчжурская династия Цин управляла различными регионами через сочетание общих и особых институтов.","Ming_dynasty","Zheng He treasure ship Ming porcelain Qing map","Почему изменения политики двора не обязательно прекращают торговую активность общества?","Сравните государственную политику и действия купцов."],
["Япония: сёгунат Токугава","1603–1868 годы","Как режим Токугава обеспечивал внутреннюю стабильность и контролировал контакты?","Сёгунат Токугава укреплял власть через иерархию даймё, чередующееся пребывание в Эдо и регулирование внешних контактов. Япония не была полностью изолирована: существовали ограниченные, но важные связи через Нагасаки и другие каналы.","Битва при Сэкигахаре произошла в 1600 году.","Сёгунат Токугава был учреждён в 1603 году.","Городская культура и торговля развивались при строгой политической иерархии.","Tokugawa_shogunate","Edo period ukiyo-e Tokugawa castle map","Как контроль над элитами и внешними контактами мог укреплять режим?","Укажите инструменты контроля и ограничения этой модели."],
["Научная революция и новые методы знания","XVI–XVII века","Как менялись способы проверять утверждения о природе?","Научная революция включала наблюдения, математические модели, инструменты и публичные споры о знаниях. Она не была простой заменой «суеверия на науку» за одно поколение: новые методы сосуществовали с религиозными представлениями и зависели от патроната и институтов.","Коперник предложил гелиоцентрическую модель в XVI веке.","Галилей использовал телескопические наблюдения и вступал в конфликт с церковными властями.","Научное знание развивается через спор, проверку и накопление методов.","Scientific_Revolution","Galileo telescope scientific revolution diagrams","Что делает объяснение научно убедительнее одного авторитетного утверждения?","Назовите наблюдение, проверку и роль альтернативных гипотез."],
["Практикум 14: раннее Новое время как глобальная система","1400–1750 годы","Почему рост европейской морской экспансии не означает, что Европа была центром всех процессов?","Сопоставьте океанские маршруты с торговлей Индийского океана, азиатскими империями и африканскими государствами. Европейские державы меняли масштаб колониального насилия и торговли, но входили в уже существовавшие сети. Хороший ответ объясняет изменение баланса силы и преемственность обмена.","Индийский океан имел развитые торговые сети до португальских экспедиций.","Колониальные системы увеличили принудительное перемещение людей и ресурсов.","Азиатские империи сохраняли значительную политическую и экономическую силу.","Early_modern_period","early modern world trade routes map 1500","Напишите сравнительный ответ: что изменилось после 1500 года и что продолжило существовать?","Поддержите вывод примерами из минимум двух регионов."]
]],
["Россия и Евразийская империя, 1500–1800","Как Московское государство стало империей и какую цену имели реформы?","Централизация, крепостное право, модернизация",[["Опричнина","Политика Ивана IV 1565–1572 годов с отдельным царским доменом, конфискациями и репрессиями."],["Крепостное право","Правовые и социальные формы зависимости крестьян, усиливавшиеся в России раннего Нового времени."],["Имперская экспансия","Расширение контроля государства на новые территории и населения."]],"https://openstax.org/books/world-history-volume-2/pages/3-introduction","Расширение Московского государства сопровождалось войнами, дипломатией и интеграцией разных народов. Иван IV усиливал царскую власть ценой репрессий и затяжных конфликтов; Смутное время показало уязвимость династии и институтов. Пётр I перестроил армию, администрацию и культуру элит ради великодержавных целей. Эти преобразования не освобождали общество автоматически: крепостная зависимость сохранялась, а расходы государства распределялись неравномерно.","При оценке реформ задайте два вопроса: какие государственные возможности выросли и кто оплатил этот рост налогами, трудом или военной службой?",[
["Иван IV: централизация, опричнина и войны","1547–1584 годы","Укрепила ли опричнина государство без серьёзных издержек?","Иван IV расширил территорию на Волгу и усилил царскую идеологию, но опричнина сопровождалась конфискациями, насилием и разрушением доверия между элитами. Ливонская война потребляла ресурсы, а результаты экспансии оказались неоднозначными.","Казань была взята в 1552 году, Астрахань — в 1556 году.","Опричнина действовала в 1565–1572 годах.","Ливонская война завершилась без достижения всех целей Москвы.","Ivan_the_Terrible","Ivan the Terrible painting Kazan Kremlin historical map","Как отличить усиление полномочий правителя от устойчивого укрепления институтов?","Сравните краткосрочный контроль с долгосрочными ресурсами и последствиями."],
["Смутное время и восстановление династии","1598–1613 годы","Почему династический кризис превратился в кризис всего государства?","Смена династии, голод, социальные конфликты и иностранное вмешательство ослабили государство. Разные силы действовали с различными целями; избрание Михаила Романова восстановило династическую власть, но не устранило долгосрочные социальные противоречия.","Голод 1601–1603 годов усилил кризис.","Польско-литовские и шведские силы вмешивались в конфликт в разные периоды.","Земский собор избрал Михаила Романова в 1613 году.","Time_of_Troubles","Time of Troubles Russian historical painting","Почему голод сам по себе не объясняет Смуту, но мог резко усилить политический кризис?","Постройте объяснение из взаимосвязанных факторов."],
["Романовы и общество XVII века","1613–1700 годы","Как государство восстанавливалось и одновременно усиливало зависимость крестьян?","Романовы укрепляли фискальные и военные институты, расширяли территорию и договаривались с элитами. Соборное уложение 1649 года закрепило важные формы крепостной зависимости. Церковный раскол Никона и сопротивление старообрядцев демонстрируют конфликты вокруг реформы и авторитета.","Соборное уложение принято в 1649 году.","Церковные реформы патриарха Никона привели к расколу.","Сибирская экспансия включала торговлю, налоги, насилие и взаимодействие с коренными народами.","Tsardom_of_Russia","Romanov dynasty 17th century Russian icon map Siberia","Как государственное строительство могло усилить армию и налоговую базу, ограничивая свободу части населения?","Покажите выигрыши государства и социальную цену."],
["Пётр I и Северная война","1682–1725 годы","Почему реформы Петра I были связаны с войной и административной перестройкой?","Пётр I перестраивал армию, флот, налоги и бюрократию, стремясь изменить международное положение России. Победа в Северной войне укрепила её роль на Балтике, но мобилизация требовала тяжёлых ресурсов и принудительного труда. Европейские культурные практики распространялись прежде всего среди элит.","Северная война длилась с 1700 по 1721 год.","Санкт-Петербург основан в 1703 году.","Табель о рангах 1722 года перестраивала государственную службу.","Peter_the_Great","Peter the Great portrait Saint Petersburg early city","Была ли модернизация Петра в первую очередь общественным проектом или проектом государства?","Используйте аргументы о целях реформ и распределении их издержек."],
["Екатерина II, Просвещение и имперская экспансия","1762–1796 годы","Почему просвещённые идеи сочетались с сохранением крепостного права?","Екатерина II использовала язык Просвещения и реформировала административные институты, но самодержавие и крепостная система сохранялись. Восстание Пугачёва показало напряжение среди крестьян и казаков; разделы Речи Посполитой и войны расширили империю.","Уложенная комиссия собралась в 1767 году, но не создала новый кодекс.","Восстание Пугачёва произошло в 1773–1775 годах.","Разделы Речи Посполитой в конце XVIII века расширили российскую территорию.","Catherine_the_Great","Catherine the Great portrait Russian Empire map 18th century","Почему язык реформ не гарантирует расширения прав для всех групп?","Сравните декларации, практические решения и положение разных обществ."],
["Крепостное право, сословия и повседневность","XVII–XVIII века","Как сословное устройство определяло возможности человека?","Российское общество было неоднородным: дворянство, духовенство, горожане, государственные и помещичьи крестьяне имели разные обязанности и права. Государство зависело от налогов и службы, а крестьяне несли большую часть производственной нагрузки. Повседневная жизнь отличалась по регионам и типу землевладения.","Крепостная зависимость усиливалась в раннее Новое время.","Дворянство получало привилегии, связанные со службой и собственностью.","Крестьяне сопротивлялись, уходили, подавали жалобы и использовали доступные правовые практики.","Serfdom_in_Russia","Russian serfs 18th century painting peasant village","Какие источники позволили бы увидеть крестьян не только глазами помещиков?","Предложите тип источника и объясните ограничения сохранившегося материала."],
["Практикум 15: сравнить реформы сверху","XVI–XVIII века","Как оценивать государственную модернизацию по международным критериям?","Сопоставьте реформы Петра I и Екатерины II с преобразованиями других империй. Анализируйте военную эффективность, администрацию, экономику, образование и политические права отдельно. Государство может модернизировать армию и бюрократию без создания представительных институтов.","Реформы могли расширять возможности государства и одновременно усиливать повинности.","Влияние идей Просвещения зависело от политической структуры.","Сравнение по нескольким критериям позволяет избежать простой оценки «успех/провал».","Russian_Empire","Russian Empire Peter Catherine historical timeline map","Напишите тезис о двух последствиях реформы Петра и одном ограничении их эффекта.","Используйте долгосрочную перспективу и различия социальных групп."]
]],
["Атлантический мир, колониализм и рабство","Как океанская экспансия изменила население, экономику и власть?","Колониализм, рабство и обмен",[["Колониализм","Политическое и экономическое подчинение территории внешней державе."],["Работорговля","Принудительное перемещение людей и продажа их труда как собственности."],["Меркантилизм","Политика, стремившаяся контролировать торговлю и ресурсы ради силы государства."]],"https://openstax.org/books/world-history-volume-2/pages/4-introduction","Формирование Атлантического мира связывало Европу, Африку и Америки через торговлю, завоевание, миграции и принудительный труд. Европейские колониальные системы опирались на местных посредников и менялись по регионам; трансатлантическая работорговля переместила миллионы африканцев насильственно. Колониализм нельзя объяснить только экономической выгодой: он также строился на военной силе, расовых идеологиях и правовых режимах.","Рассмотрите товар, например сахар: проследите землю, труд, капитал, транспорт, потребителя и власть, которая охраняет всю цепочку.",[
["Португальская и испанская экспансия","XV–XVI века","Какие технологии и институты сделали океанские маршруты возможными?","Морская экспансия опиралась на навигационные знания, кораблестроение, финансирование, государственную поддержку и соперничество. Завоевание Америк сопровождалось насилием и эпидемиями; торговля меняла мировые цены и движение металлов. Навыки мореплавания существовали также в азиатских и африканских сетях.","Васко да Гама достиг Индии морским путём в 1498 году.","Испанская корона финансировала экспедиции и колониальные институты.","Торговые пути в Индийском океане существовали задолго до португальского присутствия.","Age_of_Discovery","Age of Discovery world map caravel","Почему технология корабля сама по себе не объясняет успех экспансии?","Добавьте капитал, государственные институты и существующие торговые сети."],
["Колумбов обмен: экология, болезни, питание","После 1492 года","Как биологические перемещения изменили общества обоих полушарий?","Перемещение культур, животных, болезней и людей изменило сельское хозяйство и демографию. Картофель, кукуруза и другие растения изменили рационы за пределами Америк; европейские животные и болезни радикально преобразовали многие американские общества. Обмен был асимметричным из-за завоевания и принуждения.","Картофель стал важной культурой в Евразии и Африке.","Болезни привели к огромной смертности среди коренных американцев.","Экологические изменения происходили по-разному в отдельных регионах.","Columbian_exchange","Columbian exchange map potatoes maize horses cattle","Почему один и тот же процесс дал разные результаты в Европе, Африке и Америке?","Укажите условия региона, политический контекст и один биологический фактор."],
["Трансатлантическая работорговля","XVI–XIX века","Как рабство стало системной частью атлантической экономики?","Колониальные плантации использовали принудительный труд африканцев и их потомков. Работорговля была связана с европейским капиталом, американскими производствами, африканскими политическими посредниками и насилием над пленёнными людьми. Ответственность и формы участия различались, но принудительное перемещение стало ключевым механизмом атлантической экономики.","Миллионы африканцев были насильственно перевезены через Атлантику.","Сахарные плантации Бразилии и Карибского бассейна стали крупными потребителями рабского труда.","Рабство формировалось через законы, насилие, рынки и расовые категории.","Atlantic_slave_trade","transatlantic slave trade map ship diagram historical","Как объяснить систему рабства, не сводя её к жадности отдельных торговцев?","Разберите институты, рынки, закон и идеологию."],
["Плантации, сахар и мировые рынки","XVI–XVIII века","Как производство одного товара связывало континенты?","Сахар, табак, хлопок и другие товары соединяли плантации, кредит, перевозку и потребление. Масштабное производство требовало земли, инвестиций и принудительного труда; прибыль концентрировалась неравномерно, а экологические и человеческие издержки часто переносились на колонизированные общества.","Карибские острова стали важными центрами сахарного производства.","Плантационная экономика зависела от океанской логистики и кредитных рынков.","Колониальные товары меняли потребление и социальные практики в Европе.","Plantation","Caribbean sugar plantation historical engraving","Постройте цепочку производства и распределения сахара, обозначив, где находилась власть.","Найдите минимум трёх разных участников и покажите неравенство в выгодах."],
["Сопротивление коренных народов и порабощённых","XVI–XVIII века","Почему колониальные общества нельзя описывать только как объекты завоевания?","Коренные народы заключали союзы, воевали, переселялись, адаптировали практики и сохраняли сообщества. Порабощённые люди сопротивлялись побегами, восстаниями, саботажем и сохранением культурных традиций. Успех и формы сопротивления зависели от географии, местных союзов и устройства колониальной власти.","Война в Арауко и другие конфликты ограничивали испанское господство в отдельных регионах.","Мароны создавали общины беглых рабов в ряде колоний.","Восстания и повседневное сопротивление влияли на законы и политику.","Indigenous_resistance","Indigenous resistance colonial America historical illustration","Какие формы сопротивления могли быть менее заметны в официальных хрониках?","Сопоставьте взгляд колониальной администрации и свидетельства других групп."],
["Колониальные империи и меркантилизм","XVII–XVIII века","Как государство регулировало колониальную торговлю ради собственной силы?","Меркантилистские режимы стремились направлять торговлю через метрополию и контролировать ресурсы, порты и рынки. Колониальные общества часто нарушали правила контрабандой и локальными торговыми практиками; имперский контроль был предметом постоянных переговоров и конфликта.","Навигационные акты Англии регулировали торговлю в пользу английских интересов.","Испанские и португальские империи использовали различные торговые и административные модели.","Колониальные ограничения могли усиливать напряжение между метрополией и поселенцами.","Mercantilism","mercantilism colonial trade routes map","Почему государственные торговые ограничения могли вызывать сопротивление даже у состоятельных колонистов?","Свяжите правила, экономические интересы и политическую легитимность."],
["Практикум 16: глобальная торговая цепочка","XVI–XVIII века","Как анализировать экономическую систему через людей, товары и власть?","Выберите сахар, серебро или хлопок и обозначьте добычу/производство, труд, кредит, транспорт, налогообложение и потребление. Такой подход показывает, что мировой рынок создавался институтами и принуждением, а не был естественным пространством равноправного обмена.","Серебро из Америк влияло на рынки Евразии.","Плантационные товары связывали сельскохозяйственный труд с далёким потреблением.","Рынки были встроены в государственную силу и правовые категории.","Atlantic_world","Atlantic world trade map silver sugar textiles","Напишите объяснение, как один товар создавал последствия в двух удалённых регионах.","Обоснуйте связи фактами и отметьте человеческую цену системы."]
]],
["Просвещение и революции","Почему в XVIII–XIX веках возникли новые идеи о правах, нации и власти?","Революция, права и идеология",[["Суверенитет народа","Идея, что законная политическая власть исходит от народа или политического сообщества."],["Либерализм","Традиция идей о правах, правовом ограничении власти и индивидуальных свободах."],["Национализм","Представление о нации как ключевом источнике политической принадлежности или государственности."]],"https://openstax.org/books/world-history-volume-2/pages/5-introduction","Просвещение и революции изменили политический язык: права, конституция, гражданство и суверенитет получили новые значения. Однако универсальные декларации часто сосуществовали с рабством, колониальным господством и исключением женщин. Американская, Французская, Гаитянская и латиноамериканские революции имели общие идеи, но отличались социальными коалициями, военными условиями и итогами.","Сопоставьте, кто провозглашал права и кто реально получал их в законе и повседневной жизни.",[
["Просвещение: разум, права и власть","XVII–XVIII века","Как идеи политических философов меняли язык легитимности?","Мыслители Просвещения спорили о естественных правах, общественном договоре, веротерпимости и разделении властей. Идеи приобретали силу в конкретных политических конфликтах и печатной культуре; они не имели единого значения и могли использоваться для разных проектов.","Локк обсуждал естественные права и согласие управляемых.","Монтескьё анализировал разделение властей.","Идеи Просвещения сосуществовали с колониализмом и ограниченным политическим участием.","Age_of_Enlightenment","Enlightenment thinkers portraits books salon painting","Почему философская идея сама по себе не вызывает революцию?","Добавьте политическую ситуацию, группы интересов и каналы распространения."],
["Американская революция и конституция","1765–1789 годы","Как колонисты сочетали идею свободы с сохранением рабства?","Споры о налогах, представлении и имперской власти привели к независимости тринадцати колоний. Конституционный порядок создал республиканские институты, но рабство сохранялось, а коренные народы и женщины не получали равных политических прав.","Декларация независимости принята в 1776 году.","Конституция США была разработана в 1787 году.","Рабство стало центральным противоречием американского политического порядка.","American_Revolution","Declaration of Independence painting US Constitution historical","Как противоречие между идеалом равенства и социальной практикой повлияло на раннюю республику?","Обозначьте группы, включённые и исключённые из прав."],
["Французская революция: кризис и падение монархии","1789–1792 годы","Почему финансовый кризис перерос в революцию политического порядка?","Долги монархии, сословные привилегии, хлебный кризис и идеи суверенитета народа подорвали старый режим. В 1789 году Генеральные штаты превратились в Национальное собрание, а народная мобилизация и волнения изменили ход событий. Революция включала разные группы с неодинаковыми целями.","Взятие Бастилии произошло 14 июля 1789 года.","Декларация прав человека и гражданина провозгласила новые принципы прав и нации.","Революционные события развивались через решения элит и народное давление.","French_Revolution","French Revolution Tennis Court Oath Bastille painting","Почему финансовый кризис стал революционным именно в конкретных политических условиях Франции?","Свяжите структурные причины, идеи и непосредственные события."],
["Террор, Наполеон и наследие революции","1792–1815 годы","Как революция привела к республике, террору и империи?","Военные угрозы, внутренние конфликты и борьба за власть радикализировали революцию. Террор сопровождался репрессиями, а Наполеон закрепил часть правовых и административных изменений, одновременно установив авторитарное правление и ведя завоевательные войны.","Франция стала республикой в 1792 году.","Наполеон пришёл к власти в 1799 году и короновался императором в 1804 году.","Наполеоновский кодекс распространял некоторые правовые принципы, но закреплял гендерные ограничения.","Napoleon","Napoleon Coronation painting French Revolution timeline","Как революционные принципы могут пережить падение революционного режима?","Разведите правовые изменения, политические права и военную экспансию."],
["Гаитянская революция и рабство","1791–1804 годы","Почему Гаитянская революция изменила мировую историю свободы?","Восстание порабощённых людей в Сен-Доминго переросло в революцию, которая уничтожила рабство и привела к независимости Гаити. Конфликт включал внутренние революционные силы и борьбу с европейскими державами; он показал, что универсальные идеи свободы могут быть радикализированы самими исключёнными группами.","Восстание началось в 1791 году.","Гаити объявила независимость в 1804 году.","Революция вызвала страх перед восстаниями рабов и повлияла на политику рабства в Атлантическом мире.","Haitian_Revolution","Haitian Revolution Toussaint Louverture painting","Почему Гаитянская революция бросала вызов границам революционных идей Франции и Америки?","Сравните провозглашённые права с социальным устройством и исходами."],
["Латиноамериканские войны за независимость","1808–1830-е годы","Почему независимость не автоматически создавала устойчивую демократию?","Кризис испанской и португальской монархий, местные элиты и народная мобилизация привели к возникновению новых государств. После независимости политическая власть часто концентрировалась у военных лидеров, а социальные и расовые иерархии сохранялись.","Симон Боливар играл ключевую роль в северной части Южной Америки.","Бразилия получила независимость в 1822 году в иной политической форме, чем испанская Америка.","Границы новых государств и гражданские институты менялись в XIX веке.","Latin_American_wars_of_independence","Simon Bolivar independence Latin America map painting","Почему политическая независимость и социальное равенство — разные достижения?","Покажите разницу между сменой суверенитета и изменением общества."],
["Практикум 17: сравнить революции","XVIII–XIX века","Какие условия определяют исход революции?","Сравните американскую, французскую и гаитянскую революции по причинам, составу участников, войне, рабству и политическим итогам. Избегайте единой универсальной модели: революции могли создавать республики, империи или новые формы исключения, даже когда использовали схожий язык прав.","Экономические кризисы взаимодействовали с идеями и политическими институтами.","Социальная коалиция влияла на направление реформ.","Международная война могла усиливать радикализацию и ограничивать выбор участников.","Atlantic_Revolutions","American French Haitian revolutions comparative timeline","Напишите сравнительный тезис: чем различались результаты двух революций и почему?","Используйте явный критерий сравнения и причинное объяснение."]
]],
["Промышленная революция и социальные изменения","Как фабрики, энергия и новые рынки изменили жизнь и мировую экономику?","Индустриализация и труд",[["Индустриализация","Расширение промышленного производства и связанной с ним экономики."],["Урбанизация","Рост городов и доли населения, живущего в них."],["Социализм","Разные политические и экономические традиции, критикующие капиталистическое неравенство."]],"https://openstax.org/books/world-history-volume-2/pages/6-introduction","Промышленная революция началась в Британии при сочетании угля, капитала, технологий, рынков, институтов и трудовых отношений. Фабричное производство увеличило выпуск товаров, но города столкнулись с загрязнением, тесным жильём и опасными условиями работы. Индустриализация создала новые классы и политические движения; со временем она распространилась в Европу, Северную Америку и другие регионы.","Выберите простой предмет — ткань или железный инструмент — и сравните изготовление в ремесленной мастерской и на фабрике.",[
["Почему промышленный переворот начался в Британии?","XVIII век","Как набор условий сделал механизацию устойчивым процессом?","Британия располагала углём, капиталом, рынками, торговыми связями и институциональными условиями, помогавшими внедрять машины. Ни один фактор в одиночку не объясняет индустриализацию: изобретения работают, когда есть энергия, спрос, навыки и организации.","Паровая машина улучшалась несколькими поколениями изобретателей.","Текстильная отрасль стала одним из первых центров механизации.","Колониальные связи и атлантическая торговля были частью, но не единственным объяснением британского роста.","Industrial_Revolution","Industrial Revolution steam engine cotton mill","Как объяснить промышленный переворот так, чтобы не сводить его к одному изобретателю?","Свяжите минимум три экономических и технологических условия."],
["Фабрики и новый рабочий класс","XIX век","Как фабричная система изменила время, труд и семейную жизнь?","Фабричная организация концентрировала машины и рабочих, стандартизировала темп и контроль труда. Женщины и дети работали во многих отраслях; условия различались по месту и времени, а рабочие постепенно создавали ассоциации и добивались реформ.","Фабрика концентрировала капитал и контроль производства.","Рабочий день и безопасность регулировались неодинаково по странам и периодам.","Профсоюзы и трудовое законодательство возникали через конфликты и политическое давление.","Factory_system","19th century factory workers child labor photograph","Почему фотография фабрики должна изучаться с подписью, датой и контекстом?","Проанализируйте, что видно, и что изображение не доказывает о всех рабочих."],
["Капитализм, банки и глобальные рынки","XIX век","Как финансы связывали фабрики, государства и мировую торговлю?","Индустриализация требовала капитала для машин, железных дорог и сырья. Банки, биржи, страхование и компании распределяли риски и прибыль, но также усиливали кризисы и неравенство. Мировые рынки связывали фабричные центры с поставщиками хлопка, металла, продовольствия и рынками сбыта.","Железные дороги снижали издержки перевозок и меняли географию рынков.","Кредит давал возможность расширять производство, но усиливал долговую уязвимость.","Финансовые кризисы распространялись по сетям банков, торговли и государств.","Capitalism","19th century railway stock exchange industrial city","Как железная дорога меняет не только транспорт, но и распределение экономической власти?","Покажите последствия для производителя, потребителя и региона."],
["Либерализм, социализм и рабочие движения","XIX век","Почему индустриальное общество породило конкурирующие политические идеологии?","Либералы отстаивали разные варианты прав и рыночной свободы; социалисты критиковали собственность и неравенство; консерваторы подчёркивали порядок и преемственность. Эти категории включали множество течений, менялись во времени и сочетались с национализмом.","Маркс и Энгельс критиковали капиталистические отношения и классовые конфликты.","Утопические социалисты предлагали разные модели реформирования общества.","Трудовые движения добивались права на организацию и регулирования условий труда.","Socialism","Karl Marx Friedrich Engels workers strike historical","Как социальное изменение может привести к нескольким конкурирующим политическим программам?","Свяжите интересы групп с идеями, а не приписывайте движение одной причине."],
["Вторая промышленная революция","Конец XIX — начало XX века","Как электричество, химия и сталь ускорили индустриализацию?","Новые отрасли изменили транспорт, связь, производство и городскую инфраструктуру. Электрификация, химическая промышленность, сталь и двигатель внутреннего сгорания требовали крупных организаций и инженерных навыков, усиливая конкуренцию между индустриальными державами.","Телеграф ускорял коммуникацию на больших расстояниях.","Сталь и электричество изменяли строительство и промышленное производство.","Индустриальные технологии распространялись по странам с разной скоростью.","Second_Industrial_Revolution","early electric city steel factory telegraph","Почему техническое открытие не даёт одинакового результата в разных странах?","Учитывайте капитал, образование, ресурсы, рынки и институты."],
["Город, здоровье и массовая культура","XIX — начало XX века","Как индустриальные города создавали новые социальные проблемы и возможности?","Рост городов сопровождался проблемами санитарии, жилья и загрязнения, но также расширением образования, транспорта, массовой печати и развлечений. Муниципальные реформы, общественное здравоохранение и движения за права менялись по-разному в зависимости от политических институтов и ресурсов.","Канализация и чистая вода снижали некоторые риски заболеваний.","Массовая печать расширяла политическую и потребительскую культуру.","Городская жизнь усиливала как солидарность, так и классовые конфликты.","Urbanization","19th century industrial city street sanitation photo","Как рост города одновременно создавал угрозы здоровью и новые возможности?","Представьте два механизма и оцените, кого они затрагивали."],
["Практикум 18: анализ статистики индустриализации","XVIII–XIX века","Что статистика может рассказать о промышленном изменении — и чего не показывает?","Показатели производства, городского населения, заработков и продолжительности жизни нужно читать с учётом источника, метода подсчёта и различий классов и регионов. Средние значения могут скрывать неравномерное распределение выгод и потерь.","Рост производства не означает, что заработки растут у всех одинаково.","Статистика часто плохо отражает неформальный и неоплачиваемый труд.","Сравнение с доиндустриальным периодом требует осторожности к сопоставимости данных.","Industrial_Revolution","industrial revolution charts factory historic statistics","Сформулируйте тезис по воображаемому графику городского населения и укажите предел данных.","Используйте конкретное изменение и не делайте причинный вывод из одной корреляции."]
]],
["Нации, реформы и империи XIX века","Как национализм, отмена крепостного права и реформы меняли государства?","Нации, эмансипация, имперские государства",[["Национальное государство","Государство, легитимность которого связывают с политической нацией."],["Эмансипация","Освобождение от правовой или социальной зависимости."],["Реформа сверху","Изменение институтов, инициированное правящей властью, часто для укрепления системы."]],"https://openstax.org/books/world-history-volume-2/pages/7-introduction","XIX век был временем национальных объединений, реформ и имперского соперничества. Идеи нации и гражданства расширяли политическую мобилизацию, но часто исключали меньшинства и колонизированные народы. В России отмена крепостного права изменила юридический статус крестьян, однако земельные и политические ограничения сохранялись. Разные общества модернизировались через реформы, революции и внешнее давление.","Сравните два значения слова «свобода»: избавление от личной зависимости и реальное наличие земли, прав, дохода и голоса.",[
["Революции 1848 года и национализм","1848–1849 годы","Почему революции охватили многие европейские регионы, но дали разные результаты?","Экономические трудности, либеральные требования, национальные движения и социальное недовольство вызвали волны революций. Многие движения потерпели поражение или были подавлены, но изменили политический язык, институты и ожидания будущих реформ.","Революции затронули Францию, германские государства, Габсбургскую монархию и другие регионы.","Либеральные, национальные и рабочие требования могли конфликтовать.","Некоторые реформы и национальные идеи продолжили развиваться после поражения восстаний.","Revolutions_of_1848","1848 revolutions Europe barricades historical painting","Почему общая волна революций не привела к одинаковым политическим итогам?","Сравните состав участников, цели элит и силу государства."],
["Объединение Италии и Германии","1859–1871 годы","Как национальное объединение создавалось через дипломатию и войну?","Италия и Германия объединились через сочетание националистических движений, войн, династической политики и дипломатии. Объединение не было только «волей народа»: лидеры и институты формировали границы нового государства, а меньшинства и региональные различия сохранялись.","Королевство Италия провозглашено в 1861 году.","Германская империя была провозглашена в 1871 году.","Объединение усилило национальные государства и изменило баланс сил в Европе.","German_unification","German unification 1871 painting map Italy unification","Почему национальная идея нуждается в военных, дипломатических и институциональных механизмах?","Свяжите идеологию с конкретными решениями лидеров."],
["Отмена крепостного права в России","1861 год","Почему эмансипация крестьян не решила земельный вопрос?","Реформа Александра II отменила личную зависимость помещичьих крестьян, но наделы, выкупные платежи и общинные механизмы ограничивали возможности многих семей. Реформа была крупным изменением, проведённым сверху, и одновременно компромиссом с землевладельцами и государством.","Манифест об отмене крепостного права был издан в 1861 году.","Условия наделов и платежей отличались по регионам.","Юридическая свобода и экономическая самостоятельность — разные измерения изменения.","Emancipation_reform_of_1861","Alexander II emancipation 1861 Russian peasants painting","Как оценить реформу, учитывая и правовую перемену, и материальные ограничения?","Определите критерии успеха и интересы разных групп."],
["Реформы, революционные движения и империя в России","1860–1905 годы","Почему реформы сверху не устранили кризис самодержавия?","Судебные, земские, военные и образовательные реформы меняли институты, но не создавали полноценного парламентского контроля. Индустриализация и социальные конфликты усиливали политическую мобилизацию; революционные движения включали разные идеологии и группы.","Земская реформа 1864 года создала ограниченное местное самоуправление в части губерний.","Народнические движения искали социальную опору в крестьянстве.","Промышленный рост создал новые рабочие сообщества и политические сети.","Russian_Empire","Russian zemstvo 19th century factory workers historical","Почему модернизация экономики может усиливать политические требования?","Укажите изменение социальной структуры и ограничение институтов."],
["Гражданская война в США и отмена рабства","1861–1877 годы","Как война изменила федерацию и правовой статус порабощённых людей?","Гражданская война возникла из длительного конфликта вокруг рабства, его расширения и власти федерального правительства. Победа Союза привела к отмене рабства, но реконструкция встретилась с насилием и политическим сопротивлением; расовое равенство не возникло автоматически.","Прокламация об освобождении 1863 года изменила цели войны и правовой статус рабства на мятежных территориях.","13-я поправка отменила рабство в 1865 году.","В период Реконструкции действовали как новые гражданские права, так и насильственное противодействие им.","American_Civil_War","American Civil War emancipation historical photograph","Почему победа в войне и принятие поправки не гарантируют равенство в повседневной жизни?","Сравните закон, исполнение закона и социальное сопротивление."],
["Япония Мэйдзи и новые государства","1868–1912 годы","Как давление извне ускорило модернизацию Японии?","Реставрация Мэйдзи перестроила государственные институты, армию, образование и промышленность. Руководители использовали иностранные образцы выборочно, стремясь сохранить самостоятельность и усилить международный статус. Модернизация сопровождалась социальными потрясениями и имперскими амбициями.","Реставрация Мэйдзи началась в 1868 году.","Япония создала призывную армию и новую централизованную администрацию.","Промышленное укрепление сопровождалось войнами и колониальной экспансией.","Meiji_Restoration","Meiji Japan modernization historical photograph","Как внешняя угроза может стимулировать реформу, но не определить её точный путь?","Укажите внутренние политические решения и выбранные образцы."],
["Практикум 19: сравнение реформ сверху","XIX век","Как сравнить реформы в России и Японии по результатам и человеческой цене?","Обе страны перестраивали государственные институты под давлением международной конкуренции, но различались социальной структурой, ресурсами и масштабом политического участия. Сравните армию, образование, экономику, права и положение сельского населения.","Реформы могли укреплять государство быстрее, чем расширять права.","Внешнее давление влияло на повестку, но не диктовало все решения.","Модернизация создаёт новые возможности и новые формы принуждения.","Modernization","Meiji Japan Russian Empire reform comparison images","Напишите сравнительный тезис по двум критериям и одному общему ограничению реформ.","Используйте конкретные примеры из обоих случаев."]
]],
["Империализм, Азия и Африка","Почему индустриальные державы расширяли колониальный контроль и как сопротивлялись подчинённые общества?","Империализм и антиколониальные ответы",[["Империализм","Расширение политического, военного или экономического влияния над другими территориями."],["Сфера влияния","Территория, где внешняя держава добивается особых экономических или политических прав."],["Антиколониальное движение","Политические и социальные кампании против внешнего господства."]],"https://openstax.org/books/world-history-volume-2/pages/8-introduction","Индустриальные державы стремились контролировать сырьё, рынки, стратегические маршруты и престиж, оправдывая экспансию расовыми и цивилизаторскими идеологиями. Но колонизация не была односторонним процессом: африканские и азиатские общества сопротивлялись, договаривались, реформировались и использовали противоречия между державами. Империализм менял границы и экономические структуры, часто закрепляя неравное распределение власти.","Сравните карту границ до и после колониального раздела с рассказом местного общества: граница государства может скрывать перемены в земле, налогах и труде.",[
["Раздел Африки и Берлинская конференция","1880-е — начало XX века","Почему европейские границы не отражали автоматически местные общества?","Европейская экспансия в Африке ускорилась во второй половине XIX века под влиянием соперничества, технологий, торговли и стратегических интересов. Берлинская конференция регулировала европейские претензии, но африканские государства и народы продолжали сопротивляться и договариваться; границы часто пересекали существующие связи.","Берлинская конференция проходила в 1884–1885 годах.","Эфиопия сохранила независимость после победы при Адуа в 1896 году.","Колониальное управление различалось по форме и интенсивности.","Scramble_for_Africa","Scramble for Africa map Berlin Conference historical","Почему политическая карта колоний не объясняет сама по себе способы реального контроля?","Добавьте военную силу, местные союзы, экономику и сопротивление."],
["Британская Индия и антиколониальные реформы","XVIII–XX века","Как колониальное управление меняло экономику и политическую мобилизацию Индии?","Британский контроль развивался через Ост-Индскую компанию, военную силу, налоги и позднейшую коронную администрацию. Железные дороги и бюрократия сосуществовали с изменениями землевладения, экономическими конфликтами и политическим сопротивлением. Национальные движения были разнообразными и менялись во времени.","Восстание 1857 года стало крупным антибританским выступлением.","Индийский национальный конгресс основан в 1885 году.","Экономические и образовательные изменения создавали новые политические сети.","British_Raj","British India railway colonial map Indian independence movement","Как институты, созданные колониальной властью, могли использоваться и против неё?","Проследите непредвиденный эффект образования, транспорта или администрации."],
["Китай: опиумные войны и неравные договоры","1839–1901 годы","Как внешнее давление и внутренний кризис ослабили Цинскую империю?","Опиумные войны привели к уступкам и неравным договорам, которые расширяли права иностранных держав в Китае. Внутренние восстания, фискальные проблемы и реформаторские конфликты усиливали кризис династии. Китайские реакции включали сопротивление, реформы и националистические движения.","Первая опиумная война шла в 1839–1842 годах.","Тайпинское восстание стало одним из самых разрушительных конфликтов XIX века.","Иностранное давление взаимодействовало с внутренними проблемами, а не заменяло их.","Opium_Wars","Opium Wars Qing China historical painting treaty port","Почему объяснение кризиса Китая только европейским империализмом неполно?","Сочетайте внешние и внутренние факторы и объясните их связь."],
["Япония, Корея и соперничество империй","XIX — начало XX века","Как модернизация Японии перешла в региональную экспансию?","Япония укрепила государство и армию, а затем стала имперской державой. Победы над Китаем и Россией изменили региональный баланс, но сопровождались колониальным господством и принуждением. Корея оказалась в центре соперничества и была аннексирована Японией в 1910 году.","Япония победила Цин в войне 1894–1895 годов.","Русско-японская война завершилась в 1905 году.","Аннексия Кореи в 1910 году создала систему колониального управления.","Japanese_imperialism","Russo-Japanese War historical photograph Korea occupation map","Почему модернизацию нельзя оценивать только по военным победам?","Рассмотрите положение колонизированного общества и долгосрочные последствия."],
["Сопротивление и адаптация в колониальной Африке","XIX — начало XX века","Почему исход колониального сопротивления зависел от разных условий?","Африканские общества использовали военное сопротивление, дипломатические союзы, религиозные движения и политические реформы. Некоторые государства смогли одержать победы, другие были завоёваны; исходы зависели от оружия, логистики, союзов и внутренней организации, а не от одной «технологической отсталости».","Эфиопия победила итальянскую армию при Адуа в 1896 году.","Самори Туре и другие лидеры сопротивлялись французской экспансии.","Колониальная власть часто опиралась на местных посредников и меняла существующие элиты.","African_resistance_to_colonialism","Battle of Adwa Ethiopian historical painting","Какие факторы помогают объяснить победу одного сопротивления и поражение другого?","Сравните организацию, союзы, ресурсы и стратегию."],
["Научный расизм и оправдание империи","XIX — начало XX века","Как идеи и классификации использовались для оправдания неравной власти?","Имперская экспансия сопровождалась расовыми теориями, псевдонаучными иерархиями и языком «цивилизационной миссии». Эти идеи не просто отражали предрассудки: они влияли на право, образование, труд и насилие, но также оспаривались учёными, активистами и колонизированными обществами.","Расовые псевдонаучные теории претендовали на биологическое обоснование иерархии.","Имперские администрации использовали классификации для управления населением.","Антиколониальные и антирасистские движения критиковали эти идеи.","Scientific_racism","colonial exhibition poster imperial propaganda historical","Как визуальная пропаганда превращала политические интересы в видимость «естественного порядка»?","Разберите изображение по аудитории, цели, символам и умолчаниям."],
["Практикум 20: сравнить колониальные системы","XIX — начало XX века","Почему разные империи управляли колониями по-разному?","Сравните Британскую Индию, французскую Западную Африку и японскую Корею по экономическим целям, местным институтам, принуждению и сопротивлению. Избегайте общего объяснения «империи одинаковы»: различия помогают увидеть, как действовали ресурсы, идеология и местная политика.","Экономические интересы не объясняют все формы колониального управления.","Местные элиты могли сотрудничать, сопротивляться или менять позицию.","Колониальные институты наследовались постколониальными государствами по-разному.","Imperialism","world imperialism map 1900 colonies","Напишите сравнительный ответ о двух империях и одном общем механизме господства.","Поддержите вывод фактами из обоих случаев и объясните различия."]
]],
["Первая мировая война и революции","Почему война 1914 года разрушила империи и открыла эпоху массовой политики?","Мировая война и политический кризис",[["Тотальная война","Массовая мобилизация армии, экономики и гражданского населения."],["Революция","Быстрое изменение политических институтов и отношений власти."],["Самоопределение","Идея, что народ или политическое сообщество должно участвовать в определении своего статуса."]],"https://openstax.org/books/world-history-volume-2/pages/9-introduction","Первая мировая война возникла из международного соперничества, кризисов, союзов и решений руководителей, а убийство Франца Фердинанда стало спусковым моментом. Массовая мобилизация затронула экономику и гражданское население; война разрушила Российскую, Германскую, Австро-Венгерскую и Османскую империи. В России военное напряжение взаимодействовало с земельным, рабочим и национальным вопросами, ускорив революции.","Проследите путь от дипломатического кризиса к мобилизации: каждый переход требовал решений конкретных правительств.",[
["Причины Первой мировой войны","1871–1914 годы","Почему европейский кризис летом 1914 года стал мировой войной?","Милитаризация, национализм, имперское соперничество и союзные обязательства создавали опасную международную среду, но война не была механически неизбежной. Решения руководителей во время июльского кризиса превращали локальный конфликт в континентальную войну.","Убийство Франца Фердинанда произошло 28 июня 1914 года.","Мобилизационные планы ограничивали пространство дипломатических решений.","Колониальные территории и мировые коммуникации расширили географию войны.","World_War_I","World War I alliances map 1914 Sarajevo historical photograph","Различите долгосрочные причины, повод и решения, превратившие кризис в войну.","Постройте причинную иерархию, а не список без объяснения."],
["Тотальная война и общество","1914–1918 годы","Как война изменила производство, труд и повседневную жизнь?","Государства мобилизовали промышленность, транспорт, продовольствие и население. Женщины заняли новые роли в ряде отраслей, правительства усиливали контроль над экономикой, а гражданское население переживало дефицит, бомбардировки и принудительные переселения.","Окопная война требовала массового снабжения и артиллерии.","Блокада и перебои с продовольствием влияли на гражданское население.","Военная цензура и пропаганда меняли публичную информацию.","Home_front_during_World_War_I","World War I home front women factory rationing photo","Почему фронт и тыл нельзя изучать как отдельные истории?","Свяжите производство, снабжение и опыт гражданских лиц."],
["Революции 1917 года в России","Февраль — октябрь 1917 года","Почему монархия пала и почему власть перешла к большевикам?","Война, снабжение, земельный вопрос и потеря доверия подорвали монархию в феврале 1917 года. Временное правительство не разрешило вопросы войны и земли, а Советы и партии конкурировали за легитимность. Октябрьский захват власти большевиками был результатом кризиса институтов и политических решений.","Николай II отрёкся в марте 1917 года по новому стилю.","Временное правительство продолжило участие в войне.","Большевики захватили ключевые центры власти в октябре/ноябре 1917 года.","Russian_Revolution","February Revolution 1917 Petrograd crowd historical photo","Почему февральская революция и октябрьский переворот требуют разных объяснений?","Сравните участников, цели и политические условия двух этапов."],
["Гражданская война и распад империи","1917–1922 годы","Почему Гражданская война была многосторонним конфликтом?","Война включала красных, белых, национальные движения, крестьянские восстания и иностранное вмешательство. Стороны не имели единой программы внутри лагерей, а региональные условия влияли на исход. Насилие, реквизиции и мобилизация меняли общество и укрепляли новые органы власти.","Красные и белые отличались по целям и составу, но оба лагеря были неоднородны.","Украинские, балтийские, кавказские и другие национальные движения имели собственные цели.","СССР был образован в 1922 году.","Russian_Civil_War","Russian Civil War map red white armies historical photograph","Почему карту фронтов недостаточно для объяснения исхода гражданской войны?","Добавьте поддержку населения, снабжение, организацию и региональные движения."],
["Версальская система и самоопределение","1919–1923 годы","Почему послевоенные договоры создали новые надежды и новые конфликты?","Мирные договоры изменили границы и создали новые государства, но принцип самоопределения применялся выборочно. Репарации, меньшинства, разоружение и спорные территории сформировали наследие послевоенного порядка, а колониальные народы не получили равного права решать свою судьбу.","Версальский договор был подписан в 1919 году.","Лига Наций стремилась поддерживать международное сотрудничество, но имела слабые механизмы принуждения.","Новые границы оставили множество этнических и территориальных споров.","Treaty_of_Versailles","Treaty of Versailles 1919 signing map Europe borders","Почему провозглашённый принцип самоопределения был применён неравномерно?","Сравните группу, получившую государственность, с группой, оставшейся под внешним контролем."],
["Национальные движения и революция за пределами Европы","1910–1920-е годы","Почему мировая война ускорила национализм и антиколониальные ожидания?","Военная мобилизация и обещания реформ изменили политические ожидания в Азии, Африке и на Ближнем Востоке. Национальные движения требовали независимости или реформ, но европейские державы часто стремились сохранить имперские владения. Революционные идеи распространялись через солдат, рабочих, интеллектуалов и печать.","Восстания и движения в Египте, Индии, Китае и на Ближнем Востоке имели разные цели.","Османская империя распалась после войны, но новые границы сопровождались конфликтами.","Национализм сочетался с социалистическими, религиозными и либеральными программами.","Nationalism_in_Asia","1919 nationalist movements India China Egypt historical photo","Как глобальная война могла менять политические ожидания в обществе, которое не было европейским фронтом?","Свяжите военный опыт, обещания, экономику и политическую организацию."],
["Практикум 21: причинность и последствия войны","1914–1923 годы","Какие последствия Первой мировой были структурными, а какие непосредственными?","Различайте потери и разрушения войны, падение империй, изменение границ и развитие массовой политики. Последствия зависели от национальных движений, экономических условий и решений мирного урегулирования. Многие конфликты продолжились после формального окончания войны.","Война разрушила несколько имперских систем.","Мирные договоры создали новые государства и нерешённые споры.","Революции меняли социальные отношения, но не имели одинаковых итогов.","World_War_I","World War I aftermath Europe borders timeline map","Напишите тезис о двух долгосрочных последствиях войны и объясните их механизм.","Используйте конкретное событие и покажите причинную связь."]
]],
["Межвоенный мир и авторитаризм","Почему демократии ослабевали, а авторитарные режимы усиливались в XX веке?","Кризис, идеология и диктатуры",[["Фашизм","Авторитарная ультранационалистическая идеология, прославляющая государство, лидера и мобилизацию."],["Тоталитаризм","Модель режима, претендующего на глубокий контроль над политикой и общественной жизнью; применяется с оговорками."],["Коллективизация","Объединение сельскохозяйственных хозяйств в коллективные структуры под государственным контролем."]],"https://openstax.org/books/world-history-volume-2/pages/10-introduction","Межвоенный период сочетал последствия войны, нестабильность новых демократий, экономические потрясения, национализм и идеологическую поляризацию. Фашизм и нацизм разрушали политическую конкуренцию, используя массовую мобилизацию, пропаганду и насилие. В СССР сталинская индустриализация и коллективизация усилили государственный контроль и сопровождались голодом и репрессиями. Кризисы создавали условия, но не делали диктатуры неизбежными.","Сравните политический плакат с независимыми свидетельствами: пропаганда важна и как сообщение, и как инструмент власти.",[
["Италия Муссолини и фашистская политика","1919–1939 годы","Как фашисты захватили власть и ограничили политическую конкуренцию?","Послевоенные конфликты, страх революции, национализм и насилие способствовали росту фашистского движения. При Муссолини режим уничтожил независимые политические институты и использовал пропаганду, корпоративистскую риторику и репрессии; поддержка общества сочеталась с приспособлением, выгодой, страхом и сопротивлением.","Муссолини пришёл к власти в 1922 году.","Фашистский режим стремился организовать массовую политику вокруг лидера и государства.","Италия была союзником нацистской Германии, но фашизм и нацизм не были полностью идентичны.","Italian_Fascism","Mussolini fascist propaganda poster March on Rome","Какие условия помогли фашизму, и какие решения конкретных институтов сделали диктатуру возможной?","Разведите кризисные условия, политические решения и механизмы насилия."],
["Нацизм, расизм и Холокост","1933–1945 годы","Как идеология превращалась в государственную политику преследования и геноцида?","Нацистская диктатура сочетала расовую идеологию, антисемитизм, разрушение права, бюрократию, пропаганду и войну. Холокост стал систематическим уничтожением европейских евреев; нацистский режим преследовал и другие группы. Изучение причин не должно превращаться в оправдание или размывание ответственности.","Гитлер стал канцлером Германии в 1933 году.","Нюрнбергские законы 1935 года лишали евреев прав.","Массовое убийство европейских евреев эскалировало в условиях войны и оккупации.","The_Holocaust","Holocaust memorial archival photograph Nazi propaganda","Как административные меры, пропаганда и война могли взаимодействовать в массовом насилии?","Сформулируйте причинную цепочку, сохраняя ответственность участников."],
["Сталинизм: индустриализация и коллективизация","1928–1939 годы","Как СССР добивался быстрого промышленного роста и какую цену заплатило общество?","Пятилетние планы концентрировали ресурсы на тяжёлой промышленности, а коллективизация преобразовала сельское хозяйство через принуждение. Государство создало новые промышленные мощности, но политика сопровождалась голодом, депортациями, сломом сельских общин и массовыми репрессиями.","Первая пятилетка началась в 1928 году.","Коллективизация вызвала сопротивление крестьян и резкое изменение сельской жизни.","Голод начала 1930-х годов затронул несколько регионов СССР, включая Украину и Казахстан.","Collectivization_in_the_Soviet_Union","Soviet collectivization historical photograph industrialization factory","Как измерить индустриальный рост, не игнорируя человеческие потери?","Сравните экономические результаты, принуждение и социальные последствия."],
["Большой террор и повседневная жизнь в СССР","1936–1938 годы и шире","Как репрессии меняли государство и повседневные отношения?","Большой террор включал массовые аресты и казни, затронувшие партийные, военные и гражданские группы. Более широкая репрессивная система включала ГУЛАГ, депортации и цензуру. Люди реагировали по-разному: страх, приспособление, карьерные стратегии, взаимопомощь и сопротивление сосуществовали.","Репрессии 1937–1938 годов затронули сотни тысяч казнённых и значительно больше арестованных.","ГУЛАГ использовал принудительный труд в различных проектах.","Архивы и свидетельства выживших позволяют изучать механизм репрессий и повседневность.","Great_Purge","Gulag historical archive Soviet society 1930s photograph","Почему массовая репрессия не объясняется только решениями одного лидера?","Рассмотрите бюрократию, стимулы, идеологию и страх."],
["Великая депрессия и реакция государств","1929–1939 годы","Почему экономический кризис подорвал доверие к существующим политическим системам?","Крах финансовых рынков, падение производства, безработица и международные взаимозависимости вызвали глубокий кризис. Правительства выбирали разные ответы: общественные программы, протекционизм, авторитарную мобилизацию или ограниченные реформы. Последствия зависели от институтов и политического выбора.","Крах фондового рынка США произошёл в 1929 году, но депрессия имела более сложные причины.","Безработица и банковские кризисы подорвали доверие к рынкам и власти.","Новый курс Рузвельта расширил роль федерального государства в экономике США.","Great_Depression","Great Depression breadline unemployment historical photograph","Почему экономический кризис может привести к разным политическим последствиям?","Сравните исходные институты и выбранные государственные меры."],
["Япония и милитаризм в межвоенный период","1918–1941 годы","Как военные элиты усилили влияние в Японии?","Экономические трудности, национализм, политическое насилие и региональные амбиции усилили позиции военных кругов. Вторжение в Маньчжурию и война против Китая расширили империалистическую экспансию. Внутренние политические институты и международные санкции влияли на дальнейшие решения.","Япония захватила Маньчжурию в 1931 году.","Полномасштабная война против Китая началась в 1937 году.","Межвоенный милитаризм был связан с имперской идеологией и политическими институтами.","Japanese_militarism","Japanese occupation Manchuria historical photograph map","Как региональная экспансия могла изменить международные отношения и внутреннюю политику?","Объясните связь внешней политики, армии и институтов."],
["Практикум 22: сравнить авторитарные режимы","1919–1939 годы","Почему фашизм, нацизм и сталинизм имеют сходства и важные различия?","Сравнение должно учитывать идеологию, устройство партии, роль лидера, экономическую политику, насилие и отношение к обществу. Категория «тоталитаризм» может выявлять определённые механизмы контроля, но не должна стирать различия между целями, социальными коалициями и жертвами режимов.","Все три режима использовали репрессии и массовую политическую мобилизацию.","Нацистская расовая политика и Холокост имели специфическую центральную роль.","Экономические и социальные модели режимов различались.","Authoritarianism","authoritarian regimes propaganda posters 1930s","Напишите сравнительный ответ о двух режимах по трём критериям.","Покажите и сходство, и различие; избегайте ложной эквивалентности."]
]],
["Вторая мировая война и геноцид","Как мировая война стала глобальным конфликтом и почему насилие достигло беспрецедентного масштаба?","Война, оккупация, Холокост",[["Оккупация","Военный контроль над территорией, не равнозначный признанному суверенитету."],["Холокост","Государственно организованное нацистское уничтожение европейских евреев."],["Геноцид","Действия с намерением уничтожить полностью или частично защищённую группу в смысле Конвенции ООН."]],"https://openstax.org/books/world-history-volume-2/pages/11-introduction","Вторая мировая война имела европейские и азиатские предыстории, а затем объединила театры боевых действий по всему миру. Оккупация, тотальная война, принудительный труд, массовые убийства и Холокост затронули военных и гражданских. Войну нельзя понимать только через победы армий: для объяснения важны ресурсы, международные союзы, политические решения и опыт людей.","Сопоставьте карту операций с дневником или фотографией: военная карта показывает движение фронта, свидетельство человека — часть повседневного опыта.",[
["От вторжения в Польшу к мировой войне","1939–1941 годы","Почему политика умиротворения и экспансия не смогли сохранить европейский мир?","Нацистская Германия разрушала послевоенный порядок и расширяла территориальные претензии; другие державы делали разные расчёты и совершали ошибки. Вторжение в Польшу в 1939 году привело к объявлению войны Британией и Францией, но война расширилась через последовательные кампании и союзы.","Германия вторглась в Польшу 1 сентября 1939 года.","Пакт Молотова—Риббентропа включал секретные договорённости о сферах влияния.","Падение Франции в 1940 году изменило стратегический баланс в Европе.","World_War_II","World War II Europe 1939 invasion Poland map","Почему объяснение начала войны требует анализа действий нескольких государств?","Укажите решения, интересы и альтернативы нескольких участников."],
["Война Германии против СССР","1941–1945 годы","Почему Восточный фронт стал центральным театром войны в Европе?","Операция «Барбаросса» началась в июне 1941 года. Война была идеологической и колонизационной по замыслу нацистского режима, сопровождалась массовыми преступлениями и огромными потерями. Советская мобилизация, промышленная эвакуация, союзники и военные решения влияли на исход.","Операция «Барбаросса» началась 22 июня 1941 года.","Сталинградская битва завершилась капитуляцией окружённых немецких сил в 1943 году.","Потери СССР включали военных и гражданских и были колоссальными.","Eastern_Front_World_War_II","Eastern Front World War II Stalingrad historical photograph map","Как объяснить перелом войны сочетанием военных, промышленных и социальных факторов?","Используйте более одного фактора и покажите их взаимодействие."],
["Война в Азии и на Тихом океане","1931–1945 годы","Почему война в Азии началась до европейской войны 1939 года?","Японская экспансия в Китае с 1931 года и полномасштабная война с 1937 года предшествовали нападению на Перл-Харбор. Конфликт включал имперскую политику, колониальные интересы, массовые преступления и борьбу за стратегические ресурсы. Азиатский театр не был второстепенным продолжением войны в Европе.","Япония атаковала Перл-Харбор 7 декабря 1941 года.","Война Китая с Японией началась в полномасштабной форме в 1937 году.","США и союзники воевали на нескольких театрах Тихого океана.","Pacific_War","Pacific War map Pearl Harbor historical photograph","Почему глобальная история войны должна учитывать азиатские конфликты до 1939 года?","Покажите последовательность событий и роль региональных причин."],
["Холокост и массовые преступления","1933–1945 годы","Как дискриминация превратилась в систематический геноцид?","Нацистская политика прошла через исключение из прав, изоляцию, депортации, массовые расстрелы и центры уничтожения. Холокост был государственно организованным уничтожением евреев Европы; также преследовались рома, люди с инвалидностью, советские военнопленные, поляки и другие группы. Анализ причин не снимает ответственности с исполнителей.","В 1941–1945 годах нацисты и их пособники убили около шести миллионов евреев.","Массовые расстрелы были важной частью Холокоста на оккупированных территориях СССР.","Документы, свидетельства выживших и материальные следы взаимно дополняют друг друга.","The_Holocaust","Holocaust memorial Auschwitz archive photograph","Какие этапы политики сделали массовое уничтожение возможным?","Постройте последовательность и опирайтесь на проверенные документы."],
["Оккупация, сопротивление и гражданские люди","1939–1945 годы","Почему опыт войны различался у разных гражданских обществ?","Оккупированные общества переживали принудительный труд, голод, репрессии, сотрудничество с оккупационными властями и сопротивление. Позиции людей не всегда укладываются в простую бинарность; выборы происходили под давлением риска, идеологии и обстоятельств. Источники должны отражать разные группы и регионы.","Оккупационные режимы применяли разные формы контроля и наказания.","Сопротивление включало вооружённые сети, помощь преследуемым и повседневное неповиновение.","Гражданские потери были важнейшей частью общей истории войны.","Resistance_during_World_War_II","World War II resistance occupied Europe civilian archive","Почему один источник не может представлять опыт всех жителей оккупированной страны?","Сравните свидетельства по происхождению, группе и обстоятельствам."],
["Ядерное оружие, завершение войны и новый порядок","1945 год","Почему завершение войны породило новый международный и моральный кризис?","Поражение Германии и Японии изменило мировой баланс сил. Атомные бомбардировки Хиросимы и Нагасаки остаются предметом исторических споров о военных расчётах, капитуляции и человеческой цене; одновременно опыт войны способствовал созданию ООН и международных норм.","Германия капитулировала в мае 1945 года.","Атомные бомбы были сброшены на Хиросиму и Нагасаки в августе 1945 года.","ООН была основана в 1945 году.","Atomic_bombings_of_Hiroshima_and_Nagasaki","Hiroshima 1945 archival photograph UN founding","Как оценивать решение в условиях войны, сопоставляя документированные цели и человеческие последствия?","Различите установленные факты, спорные интерпретации и моральные суждения."],
["Практикум 23: доказательства и память о войне","1939–1945 годы","Как изучать преступления и память о Второй мировой без упрощения?","Сопоставьте документы, свидетельства очевидцев, фотографии, статистику и позднейшие мемориальные практики. Каждый источник имеет ограничения, но это не делает установленные преступления спорными по произвольному желанию. Историческая память важна для понимания общества после войны, но не заменяет исследование события.","Документированные факты подтверждаются независимыми источниками разных типов.","Свидетельство очевидца особенно ценно для опыта человека, но не всегда для общей статистики.","Память о войне меняется, а научное исследование опирается на методы проверки.","World_War_II","World War II memorial museum photographs historical documents","Напишите короткий ответ с тезисом, двумя доказательствами и пояснением ограничения одного источника.","Проверьте точность, происхождение свидетельств и логику вывода."]
]],
["Холодная война и деколонизация","Как соперничество сверхдержав и распад империй изменили послевоенный мир?","Биполярность, независимость, развитие",[["Сдерживание","Стратегия предотвращения действий противника угрозой неприемлемых последствий."],["Деколонизация","Прекращение колониального господства и образование независимых государств."],["Движение неприсоединения","Попытка ряда государств не включаться полностью в один из блоков холодной войны."]],"https://openstax.org/books/world-history-volume-2/pages/12-introduction","После 1945 года США и СССР создали конкурирующие блоки, но холодная война включала не только вооружения и дипломатию: она влияла на локальные войны, развитие, культуру и внутреннюю политику. Одновременно африканские и азиатские народы добивались независимости. Деколонизация меняла международный порядок, но границы, экономическая зависимость и холодновоенное вмешательство усложняли путь новых государств.","Отметьте на карте независимость нескольких стран и сопоставьте её с военными союзами, экономической помощью и региональными конфликтами.",[
["Возникновение холодной войны","1945–1950-е годы","Почему союзники по Второй мировой стали соперниками?","Разногласия по безопасности, идеологии, влиянию в Европе и будущем послевоенных институтов привели к формированию блоков. Холодная война не сводилась к одной причине: взаимное недоверие и решения обеих сторон укрепляли противостояние.","Доктрина Трумэна провозглашена в 1947 году.","План Маршалла поддержал восстановление Западной Европы.","Берлинский кризис и блокада 1948–1949 годов усилили разделение Европы.","Cold_War","Cold War Europe map Berlin Airlift historical photograph","Как меры одной стороны могли усиливать ощущение угрозы у другой?","Объясните механизм взаимного недоверия и эскалации."],
["Ядерное сдерживание и локальные войны","1950–1980-е годы","Почему ядерное оружие не исключило многочисленные войны?","Ядерное сдерживание уменьшало стимулы к прямому столкновению сверхдержав, но соперничество продолжалось через союзников, помощь, перевороты и региональные войны. Корейская и Вьетнамская войны имели местные исторические причины и одновременно глобальный контекст.","Корейская война началась в 1950 году.","Карибский кризис 1962 года стал опасной точкой ядерной эскалации.","Война во Вьетнаме включала внутренние конфликты, деколонизацию и внешнее вмешательство.","Cold_War","Cuban Missile Crisis Cold War world map historical photo","Как локальный конфликт становится частью глобального соперничества, не теряя местных причин?","Разделите внутренние и внешние факторы."],
["Деколонизация Южной и Юго-Восточной Азии","1940–1970-е годы","Почему независимость Индии и соседних государств сопровождалась разными конфликтами?","Национальные движения, ослабление Британии и глобальные обстоятельства ускорили деколонизацию. Раздел Британской Индии привёл к масштабным переселениям и насилию; в других регионах независимость сопровождалась войнами и конфликтами политических идеологий.","Индия и Пакистан стали независимыми в 1947 году.","Раздел вызвал массовые миграции и межобщинное насилие.","Вьетнам, Индонезия и другие территории прошли через разные пути к независимости.","Partition_of_India","Partition of India 1947 refugee train historical photograph map","Почему независимость и мирное создание государства не всегда совпадают?","Свяжите границы, идентичность, власть и миграции."],
["Деколонизация Африки","1950–1970-е годы","Почему независимость не устранила все экономические и политические зависимости?","Независимость африканских стран проходила через переговоры, массовые движения и вооружённую борьбу. Новые государства унаследовали границы и институты колониального периода, сталкивались с проблемами развития и вмешательством внешних сил; траектории сильно различались.","Гана стала независимой в 1957 году.","В Алжире война за независимость продолжалась в 1954–1962 годах.","Колониальная экономика часто была ориентирована на экспорт сырья, что влияло на постколониальное развитие.","Decolonization_of_Africa","African independence 1960 historical photographs map","Почему независимость нельзя оценивать только по смене флага и правительства?","Учитывайте экономическую структуру, институты и международное положение."],
["Китайская революция и маоизм","1911–1976 годы","Как революция и гражданская война изменили китайское государство?","Падение Цин, республиканские кризисы, японская агрессия и гражданская война привели к созданию КНР в 1949 году. Маоистские кампании преобразовали собственность и общество, но сопровождались массовым голодом, насилием и нестабильностью.","КНР была провозглашена в 1949 году.","Большой скачок вперёд привёл к катастрофическому голоду в конце 1950-х — начале 1960-х годов.","Культурная революция 1966–1976 годов изменила образование, партийную систему и общественные отношения.","Chinese_Communist_Revolution","Chinese Revolution 1949 Mao Great Leap Forward historical","Как революционное государственное строительство могло одновременно преобразовывать и разрушать общество?","Сопоставьте заявленные цели, институты и измеримые последствия."],
["Ближний Восток и новые границы","1916–конец XX века","Как имперское наследие и региональные конфликты формировали послевоенный Ближний Восток?","Распад Османской империи, мандатная система, национальные движения, нефть и международное соперничество формировали политическую карту региона. Конфликты нельзя объяснить только древней религией или только внешним вмешательством: важны современная государственность, социальные группы и конкретные решения.","Мандатная система Лиги Наций управляла бывшими османскими территориями после Первой мировой войны.","Создание Израиля в 1948 году сопровождалось войной и массовым перемещением палестинцев.","Нефть усиливала стратегическое значение региона для мировых держав.","Middle_East","Middle East 20th century historical map decolonization","Почему современный конфликт нельзя объяснять неизменной враждой с древности?","Покажите конкретные исторические изменения, решения и интересы."],
["Практикум 24: холодная война и независимость","1945–1991 годы","Как государства Глобального Юга действовали в условиях холодной войны?","Сопоставьте деколонизацию с политикой блоков, экономической помощью и региональными конфликтами. Новые государства не были лишь пешками сверхдержав: их лидеры и общества преследовали собственные цели и могли маневрировать между союзами. Но внешнее вмешательство часто усиливало внутренние кризисы.","Движение неприсоединения создало альтернативную дипломатическую площадку.","Сверхдержавы использовали помощь, союзы и военную поддержку для усиления влияния.","Внутренние социальные конфликты имели собственную историю и не сводились к внешнему соперничеству.","Non-Aligned_Movement","Non-Aligned Movement Bandung conference historical photo map","Напишите тезис о двух уровнях причин одного конфликта холодной войны.","Укажите местные и глобальные интересы, не сводя один к другому."]
]],
["Мир после 1991 года и глобализация","Как закончилась биполярная эпоха и почему её наследие продолжает влиять на мир?","Распад государств, глобализация, память",[["Глобализация","Усиление взаимосвязей через торговлю, технологии, финансы, миграцию и культуру."],["Постсоветские государства","Независимые государства, возникшие после распада СССР в 1991 году."],["Историческая память","Общественные способы отбора, обсуждения и передачи представлений о прошлом."]],"https://openstax.org/books/world-history-volume-2/pages/13-introduction","После 1991 года мир изменился через распад СССР, независимость новых государств, ускорение коммуникаций, расширение мировых рынков и изменение международных институтов. Глобализация приносила новые возможности и неравномерные последствия. История постсоветских обществ не едина: страны по-разному строили государственные институты, определяли национальную идентичность и взаимодействовали с соседями. Современные споры о прошлом требуют особенно точного разделения факта, интерпретации и политического нарратива.","Сравните два постсоветских государства по одному общему наследию СССР и одному различию их последующего пути.",[
["Распад СССР и конец холодной войны","1985–1991 годы","Почему перестройка привела к распаду союзного государства?","Экономические трудности, политическая либерализация, национальные движения и борьба за власть ослабили союзный центр. Распад был не результатом одной причины: реформы изменили ожидания и публичную сферу, а союзные республики использовали новые политические возможности по-разному.","Перестройка и гласность начались при Горбачёве в середине 1980-х годов.","Августовский путч произошёл в 1991 году.","СССР прекратил существование в декабре 1991 года.","Dissolution_of_the_Soviet_Union","Soviet Union dissolution 1991 map Baltic independence","Почему экономический кризис не объясняет распад без политики и национальных движений?","Покажите взаимосвязь экономических, институциональных и национальных причин."],
["Постсоветские государства и разные траектории","1991 — настоящее время","Почему страны с общим советским наследием развивались неодинаково?","После 1991 года государства унаследовали разные экономические структуры, границы, языковые и национальные отношения и элитные коалиции. Политические реформы и международные связи дали разные результаты. Избегайте объяснения через «национальный характер»: анализируйте институты, ресурсы и решения.","Распад СССР создал 15 независимых государств.","Балтийские страны и страны Центральной Азии выбрали разные модели внешней и внутренней политики.","Конфликты и демократические переходы зависели от местных условий и международной среды.","Post-Soviet_states","post-Soviet states map flags historical timeline","Какие факторы позволяют объяснить различия стран без стереотипов?","Сравните институциональное, экономическое и внешнеполитическое измерения."],
["Глобализация, технологии и неравенство","1990-е годы — XXI век","Почему глобальные связи создают и возможности, и уязвимости?","Цифровые коммуникации, мировое производство, миграция и финансовые рынки усилили взаимозависимость. Выгоды распределяются неравномерно, а кризисы могут быстро переходить границы. Для исторического объяснения важно сравнивать современные изменения с прежними волнами глобализации, не объявляя нынешнюю эпоху совершенно беспрецедентной.","Контейнерные перевозки изменили стоимость и скорость глобальной торговли.","Интернет расширил информационные сети и новые формы политической мобилизации.","Глобальные кризисы показывают зависимость цепочек поставок и финансов.","Globalization","global shipping container port internet infrastructure","Как глобальная цепочка поставок передаёт локальный сбой другим странам?","Постройте причинную цепочку через производство, транспорт и спрос."],
["Память, национальная идентичность и школьные учебники","XX–XXI века","Почему общества спорят о памятниках, героях и датах?","Историческая память связана с гражданской идентичностью, образованием и политической легитимностью. Учебник может отбирать разные примеры, но исторические утверждения должны быть проверяемы. Анализируйте, какие группы представлены, какие исключены и как менялись интерпретации на протяжении времени.","Памятники и юбилеи являются источниками о памяти и политике, не только о первоначальном событии.","Открытие архивов может менять знания и общественные споры.","Различие интерпретаций не означает, что все утверждения одинаково доказаны.","Collective_memory","history textbook museum memorial historical images","Как учебник может влиять на память, не обязательно сообщая откровенную ложь?","Проанализируйте отбор фактов, пропуски и язык описания."],
["Исторические объяснения современных конфликтов","XX–XXI века","Как использовать историю, не представляя современный конфликт неизбежным?","Современные конфликты имеют ближайшие причины и более глубокие исторические контексты. Прошлое объясняет ресурсы, институты и память, но не отменяет выбора политических акторов. Избегайте схем «древняя вражда»: устанавливайте конкретные решения, изменения границ, интересы и свидетельства.","Границы и институты меняются со временем.","Исторические аналогии могут помогать, но часто скрывают различия.","Объяснение причины не является моральным оправданием действия.","Contemporary_history","modern world political map archive newspaper headlines","Как проверить, действительно ли историческая аналогия объясняет нынешний случай?","Назовите сходства, различия и предел переноса аналогии."],
["Климат, миграция и история XXI века","XX–XXI века в долгой перспективе","Как историки используют прошлое для понимания экологических изменений?","Исторические общества адаптировались к засухам, эпидемиям, изменению урожаев и миграциям, однако современный климатический кризис имеет собственные технологические и политические причины. Долгая перспектива помогает сравнивать уязвимость и адаптацию, не стирая различия масштаба и научных данных.","Экологические изменения влияли на способы земледелия и миграцию в разные эпохи.","Институты и неравенство определяют, кто может адаптироваться к кризисам.","Современные климатические выводы требуют естественно-научных данных наряду с историей.","Environmental_history","climate migration historical drought agriculture map","Как сравнить прошлую засуху с современным изменением климата, не приравнивая их автоматически?","Укажите сходство механизма и важное различие масштаба или причины."],
["Практикум 25: исторический аргумент и источники","Современность и длинная перспектива","Как построить ответ, который выдерживает критику?","Сформулируйте тезис, определите временной и региональный контекст, используйте конкретные свидетельства и поясните причинную связь. Рассмотрите альтернативное объяснение и ограничение источника. Такой метод нужен не только на экзамене, но и при чтении новостей и публичных высказываний о прошлом.","Сильный тезис отвечает на вопрос, а не повторяет его.","Доказательство должно подтверждать конкретную часть аргумента.","Контраргумент улучшает объяснение, если он рассмотрен по существу.","Historical_argumentation","historian archive research documents","Напишите абзац по схеме тезис — доказательство — рассуждение — ограничение.","Оцените точность тезиса, конкретность доказательств и логическую связь."]
]],
["Международные экзамены: мастерская историка","Как продемонстрировать знания и навыки в форматах AP, IB и Cambridge?","Экзаменационная практика",[["SAQ","Краткий ответ на исторический вопрос, часто по нескольким подпунктам."],["DBQ","Эссе, основанное на анализе набора документов."],["OPVL","Анализ происхождения, цели, ценности и ограничений источника."]],"https://apcentral.collegeboard.org/courses/ap-world-history?course=ap-world-history","Международные экзамены проверяют не только объём знаний, но и то, как вы используете доказательства. Для AP важны анализ источников, контекст, сравнение, причинность и аргументация; в IB значимы многосторонний анализ и оценка источников, а Cambridge требует самостоятельного суждения и работы с интерпретациями. Этот модуль учит базовым навыкам, но точный формат нужно сверять с выбранным экзаменом и его текущей спецификацией.","Считайте, что проверяющий не знает, что у вас в голове: ответ должен показать тезис, точный факт и объяснение, связывающее их.",[
["AP-style: источники и вопрос с выбором ответа","Экзаменационный формат","Как ответить на вопрос, основанный на тексте, карте или изображении?","Сначала прочитайте подпись, дату, источник и формулировку вопроса. Определите, какой навык проверяется: контекст, сравнение, причинность, изменение во времени или аргумент автора. Не выбирайте ответ только потому, что он содержит знакомое слово; ищите доказательство в стимуле и курсовом знании.","AP World History: Modern охватывает период примерно с 1200 года до настоящего времени.","Вопросы могут использовать тексты, карты, изображения и количественные данные.","В 2027 году College Board обновляет некоторые форматы ответов; сверяйте текущую спецификацию.","AP_World_History_Modern","AP World History document based questions map chart","Решите вопрос по источнику: запишите, какое свидетельство поддерживает выбранный ответ.","Ответьте на вопрос прямо и укажите фрагмент источника или контекст."],
["Короткий ответ: тезис и доказательство","SAQ-style","Как уместить точный исторический аргумент в несколько предложений?","Короткий ответ должен отвечать на конкретный подпункт и содержать точный пример. Полезная структура: утверждение, доказательство, объяснение. Не тратьте место на длинное вступление; каждый пункт должен выполнять требование вопроса.","Уточните временные рамки и регион до ответа.","Один конкретный исторический пример лучше расплывчатой формулировки.","Связь между доказательством и утверждением должна быть явно объяснена.","Historical_argumentation","history exam handwritten essay notebook","Ответьте в 3–5 предложениях на вопрос: как торговые сети способствовали распространению религий в Средневековье?","Тезис, точный пример, причинная связь."],
["Сравнительное эссе","Эссе и сопоставление","Как сравнивать две страны или эпохи, а не писать два независимых рассказа?","Начните с общего критерия — например, управление, экономика или социальные права. Затем сформулируйте тезис о сходстве и различии, используя сопоставимые факты из обоих случаев. Объясните, почему сходство или различие возникло.","Сравнение требует общего критерия.","Каждый пример должен быть связан с утверждением.","Различия часто объясняются контекстом, а не изолированным фактом.","Historical_argumentation","historical comparison essay notes map","Сравните две революции по участникам и политическим итогам.","Единый критерий, доказательства для обоих случаев, объяснение причин."],
["Причины, последствия и значимость","Историческое рассуждение","Как объяснить сложное событие без единственной причины?","Разделите долгосрочные условия, непосредственный повод, решения участников и структурные механизмы. Затем оцените последствия по времени и группам. Значимость события объясняется масштабом изменений, продолжительностью и тем, как оно изменило последующие возможности.","Причина не равна поводу.","Последствия могут быть непреднамеренными и неравномерными.","Историческая значимость зависит от сформулированного критерия.","Historical_causation","historical causes and consequences timeline","Напишите многопричинное объяснение начала Первой мировой войны в одном абзаце.","Иерархия причин, механизм, точные доказательства, оговорка об альтернативных объяснениях."],
["OPVL: происхождение, цель, ценность и ограничение","IB-style source analysis","Как оценивать источник, не объявляя его просто «предвзятым»?","Происхождение и цель помогают понять, что источник способен показать. Ценность и ограничения зависят от конкретного исследовательского вопроса: политическая речь полезна для анализа публичной позиции, но не обязательно отражает частное мнение автора или реакцию всего общества.","Один источник может быть ценен по одному вопросу и ограничен по другому.","Авторская позиция не делает источник автоматически бесполезным.","Сопоставление независимых источников помогает проверить заявления.","Primary_source","historical poster speech manuscript source analysis","Проведите OPVL-анализ выбранной иллюстрации или документа из курса.","Назовите происхождение и цель, привяжите ценность и ограничение к вопросу."],
["Подготовка к письменной работе и исследовательскому проекту","IB/Cambridge-style investigation","Как превратить интерес к эпохе в проверяемый исследовательский вопрос?","Хороший вопрос ограничен временем, местом и проблемой; он допускает аргументированный ответ, а не простой пересказ. Соберите первичные и вторичные источники, сравните интерпретации, отметьте ограничения и правильно укажите ссылки. Не пытайтесь доказать всё одной цитатой.","Исследовательский вопрос должен быть выполнимым при доступных источниках.","Первичные и вторичные источники выполняют разные функции.","Цитирование помогает проверить ход аргумента и избежать искажения чужого текста.","Historical_method","historian archival research library documents","Сформулируйте один исследовательский вопрос об изученной теме и назовите три нужных источника.","У вопроса есть рамки, исследуемая проблема и реалистичный план доказательств."],
["Итоговый пробный экзамен и план продолжения","Итог курса","Какие знания вы уже можете объяснить, а что нужно повторить?","В итоговой работе соедините хронологию, региональные сравнения, анализ источника и письменный аргумент. После пробного экзамена не ограничивайтесь общим процентом: разберите ошибки по типам — недостаток знаний, неверное чтение источника, слабая причинная связь или невнимательность к формулировке. Затем выберите точную экзаменационную программу для второго этапа.","Базовый курс охватывает широкую историю, но AP, IB и Cambridge имеют разные спецификации.","Официальные прошлые задания и рубрики важны для точной подготовки.","Повторение должно адресовать тип ошибки, а не только перечитывать целую тему.","AP_World_History_Modern","history exam mock test study plan timeline","Напишите короткий ответ по источнику, затем составьте список трёх тем для повторения и объясните почему.","Оцените доказательства, структуру аргумента, контекст и точность."]
]]
];
const lessons = [];
weeks.forEach(function(w, wi) {
  w[7] = w[7] || [];
  w[6] = w[6] || "";
  w[8] = null;
});
const modules = weeks.map(function(w) {
  return {title:w[0], question:w[1], skill:w[2], terms:w[3], source:w[4], overview:w[5], example:w[6], lessons:w[7]};
});
modules.forEach(function(m, wi) {
  m.lessons.forEach(function(a, di) {
    const title=a[0], period=a[1], question=a[2], summary=a[3];
    const facts=[a[4],a[5],a[6]];
    const wiki=a[7], imageSearch=a[8], examPrompt=a[9], rubric=a[10];
    const reading={
      imageSearch:imageSearch,
      examPrompt:examPrompt,
      rubric:rubric,
      example:m.example,
      source:m.source,
      terms:m.terms,
      skill:m.skill,
      weekOverview:m.overview,
      harariLens:a[11]||(
        /земледел|неолит|сельскохозяйственн/i.test(title)
          ? "Связь с Sapiens: Харари провокационно предлагает оценить земледелие не только как прогресс, но и через труд, болезни, зависимость от урожая и неравенство. Сверьте эту интерпретацию с археологическими данными и исследованиями конкретных регионов."
          : /религ|будд|ислам|христиан|иуда|конфуциан|ритуал|церков/i.test(title)
            ? "Связь с Sapiens: глава о религии предлагает рассмотреть общие системы представлений и социальные функции. Не сводите религию только к инструменту власти или сотрудничества: сравнивайте историю конкретных традиций, верования людей и источники."
            : /монет|деньг|торгов|импер|колони|капитализм|глобализац/i.test(title)
              ? "Связь с Sapiens: проследите, как деньги, империи и общие правила создают связи между незнакомыми людьми. Проверьте, кто получает выгоду, кто контролирует систему и как материальная власть сочетается с общими представлениями."
              : /научн|индустриализац|промышленн/i.test(title)
                ? "Связь с Sapiens: сопоставьте научную и промышленную революции как процессы, меняющие институты и повседневность. Большая схема полезна, но сроки и причины различались по регионам."
                : ""
      )
    };
    lessons.push([title,period,question,summary,facts,wiki,reading]);
  });
});
window.HISTORY_CURRICULUM = {weeks:modules.map(function(m){return [m.title,m.question,m.skill,m.terms,m.source,m.overview,m.example]}),lessons:lessons};
})();
